_SCANNER_PROGRESS = {"bar": None, "frac": 0.0}


def _reset_scanner_progress():
    """스캔 시작 전 진행률 바 초기화. 버킷마다 새 바를 만든다."""
    _SCANNER_PROGRESS["bar"] = None
    _SCANNER_PROGRESS["frac"] = 0.0


def _app_scanner_progress(frac, text):
    """scanner_core → st.progress 브리지. frac=None 은 불확정(구 st.spinner)."""
    try:
        if frac is not None:
            _SCANNER_PROGRESS["frac"] = float(frac)
        f = _SCANNER_PROGRESS["frac"]
        bar = _SCANNER_PROGRESS["bar"]
        if bar is None:
            _SCANNER_PROGRESS["bar"] = st.progress(f, text=text)
        else:
            bar.progress(f, text=text)
    except Exception:
        pass


def _app_scanner_log(level, msg):
    try:
        if level == "error":
            st.code(str(msg), language="bash")
        elif level == "warn":
            st.warning(str(msg))
    except Exception:
        pass


sc.set_progress_hook(_app_scanner_progress)
sc.set_log_hook(_app_scanner_log)
