def open_portfolio_alert_state_worksheet():
    """Quant_DB 의 Portfolio_Alert_State 탭. 없으면 자동 생성. (ws | None, err | None)"""
    gc = get_gspread_client()
    if gc is None:
        return None, "Google 서비스 계정(`gcp_service_account`)이 설정되지 않았습니다."
    try:
        _last_col = chr(ord("A") + len(_PORTFOLIO_ALERT_STATE_COLS) - 1)
        ws = _ws_handle(_PORTFOLIO_ALERT_STATE_TITLE)
        if ws is not None:
            try:  # 스키마 확장(4→6칸) 시 헤더 자동 갱신 — 기존 행은 빈칸 패딩
                if (ws.row_values(1) or []) != _PORTFOLIO_ALERT_STATE_COLS:
                    ws.update([_PORTFOLIO_ALERT_STATE_COLS], range_name=f"A1:{_last_col}1",
                              value_input_option="USER_ENTERED")
            except Exception:
                pass
            return ws, None
        sh = _open_quant_db()
        ws = sh.add_worksheet(title=_PORTFOLIO_ALERT_STATE_TITLE, rows=2000,
                              cols=len(_PORTFOLIO_ALERT_STATE_COLS))
        ws.update([_PORTFOLIO_ALERT_STATE_COLS], range_name=f"A1:{_last_col}1", value_input_option="USER_ENTERED")
        _invalidate_ws_handles()
        return ws, None
    except Exception as exc:
        return None, f"Portfolio_Alert_State 워크시트 열기/생성 실패: {exc}"


def _pf_alert_key(user_id: str, account: str, ticker: str) -> str:
    return f"{str(user_id).strip()}|{str(account).strip()}|{str(ticker).strip().upper()}"


@st.cache_data(ttl=300, show_spinner=False)
def load_portfolio_alert_states() -> dict:
    """Portfolio_Alert_State 전체 → {key: {"states": "...", "last_state": "..."}}."""
    ws, err = open_portfolio_alert_state_worksheet()
    if ws is None:
        return {}
    try:
        vals = ws.get_all_values() or []
    except Exception:
        return {}
    out = {}
    for r in vals[1:]:
        r = (list(r) + [""] * 6)[:6]
        key = str(r[0]).strip()
        if key:
            _sl = to_float(r[4])
            _tp = to_float(r[5])
            out[key] = {
                "states": str(r[1]).strip(),
                "last_state": str(r[2]).strip(),
                "stop_loss": float(_sl) if pd.notna(_sl) else None,
                "target_price": float(_tp) if pd.notna(_tp) else None,
            }
    return out


def save_portfolio_alert_states_bulk(user_id: str, account: str, tickers, states_csv: str) -> tuple[int, list]:
    """계좌의 여러 보유 종목 Alert_States 를 한 번에 upsert. last_state(C열)는 보존.

    개별 저장을 N번 반복하면 get_all_values 도 N번 발생한다(시트 API 낭비 + 레이트리밋).
    읽기 1회 + batch_update 1회 + 신규분 append 1회로 처리한다.
    반환: (성공 건수, 실패 티커 리스트)
    """
    ws, err = open_portfolio_alert_state_worksheet()
    if ws is None:
        return 0, list(tickers)
    try:
        vals = ws.get_all_values() or []
        row_of = {}
        for i, r in enumerate(vals[1:], start=2):
            if r and str(r[0]).strip():
                row_of[str(r[0]).strip()] = i
        now_str = _narrative_now_et_string()
        updates, new_rows, done = [], [], []
        for tk in tickers:
            key = _pf_alert_key(user_id, account, tk)
            idx = row_of.get(key)
            if idx:
                updates.append({"range": f"B{idx}", "values": [[states_csv]]})
                updates.append({"range": f"D{idx}", "values": [[now_str]]})
            else:
                new_rows.append([key, states_csv, "", now_str])
            done.append(tk)
        if updates:
            ws.batch_update(updates, value_input_option="RAW")
        for r in new_rows:
            _safe_append_rows(ws, r, value_input_option="RAW")
        load_portfolio_alert_states.clear()
        return len(done), []
    except Exception:
        return 0, list(tickers)


def save_portfolio_alert_states_setting(user_id: str, account: str, ticker: str, states_csv: str) -> tuple[bool, str]:
    """보유 종목의 알림 이벤트 설정(Alert_States)만 upsert. last_state 는 보존."""
    ws, err = open_portfolio_alert_state_worksheet()
    if ws is None:
        return False, err or "시트 열기 실패"
    key = _pf_alert_key(user_id, account, ticker)
    try:
        vals = ws.get_all_values() or []
        row_idx = None
        for i, r in enumerate(vals[1:], start=2):
            if r and str(r[0]).strip() == key:
                row_idx = i
                break
        now_str = _narrative_now_et_string()
        if row_idx:
            ws.update([[states_csv]], range_name=f"B{row_idx}", value_input_option="RAW")
            ws.update([[now_str]], range_name=f"D{row_idx}", value_input_option="RAW")
        else:
            _safe_append_rows(ws, [key, states_csv, "", now_str], value_input_option="RAW")
        load_portfolio_alert_states.clear()
        return True, ""
    except Exception as exc:
        return False, str(exc)


def save_portfolio_plan_setting(user_id: str, account: str, ticker: str,
                                stop_loss, target_price) -> tuple[bool, str]:
    """보유 종목의 손절/목표가(Stop_Loss·Target_Price)만 upsert. Alert_States/last_state 보존.
    NaN/<=0 은 빈칸(미설정)으로 저장."""
    ws, err = open_portfolio_alert_state_worksheet()
    if ws is None:
        return False, err or "시트 열기 실패"
    key = _pf_alert_key(user_id, account, ticker)

    def _cell(v):
        try:
            f = float(v)
            return f if (f == f and f > 0) else ""
        except (TypeError, ValueError):
            return ""
    sl_cell, tp_cell = _cell(stop_loss), _cell(target_price)
    try:
        vals = ws.get_all_values() or []
        row_idx = None
        for i, r in enumerate(vals[1:], start=2):
            if r and str(r[0]).strip() == key:
                row_idx = i
                break
        now_str = _narrative_now_et_string()
        if row_idx:
            ws.update([[sl_cell, tp_cell]], range_name=f"E{row_idx}:F{row_idx}", value_input_option="RAW")
            ws.update([[now_str]], range_name=f"D{row_idx}", value_input_option="RAW")
        else:
            _safe_append_rows(ws, [key, "", "", now_str, sl_cell, tp_cell], value_input_option="RAW")
        load_portfolio_alert_states.clear()
        return True, ""
    except Exception as exc:
        return False, str(exc)


def compute_auto_plan_for_holding(ticker: str, entry_price=None):
    """보유 등록용 자동 플랜 — 이메일 진입 알림과 동일 SSOT(rc.build_watchlist_plan) 계산.

    entry_price(매수가/평단) 기준으로 ATR 손절·R:R 목표를 산출. 미지정 시 최근 종가.
    반환: plan dict (stop/target/rr_label/gate 포함) | None(데이터 부족·계산 불가).
    """
    try:
        tk = str(ticker).strip().upper()
        if not tk:
            return None
        hist = cached_timing_price_history(tk)
        if hist is None or hist.empty:
            return None
        an = rc.analyze_ticker(hist)
        if not an.get("regime", {}).get("enough_data"):
            return None
        try:
            e = float(entry_price) if (entry_price is not None and float(entry_price) > 0) else None
        except (TypeError, ValueError):
            e = None
        plan = rc.build_watchlist_plan(hist, an, entry=e)
        if not plan or str(plan.get("gate")) == "na":
            return None
        stop = plan.get("stop")
        try:
            if stop is None or not np.isfinite(float(stop)) or float(stop) <= 0:
                return None
        except (TypeError, ValueError):
            return None
        return plan
    except Exception:
        return None


def auto_save_plan_after_add(user_id: str, account: str, ticker: str, entry_price) -> str:
    """종목 추가 직후 제안 플랜 자동 저장. 기존 플랜이 있으면 보존(덮어쓰지 않음).

    반환: 성공/건너뜀/실패 안내 문구(성공 메시지 뒤에 이어붙일 조각).
    """
    try:
        _key = _pf_alert_key(user_id, account, ticker)
        _st_row = (load_portfolio_alert_states() or {}).get(_key, {})
        _ex_sl = _st_row.get("stop_loss")
        _ex_tp = _st_row.get("target_price")
        if (_ex_sl is not None and _ex_sl > 0) or (_ex_tp is not None and _ex_tp > 0):
            return " · 📐 기존 플랜 유지(자동 저장 건너뜀)"
        plan = compute_auto_plan_for_holding(ticker, entry_price)
        if not plan:
            return " · 📐 플랜 자동 계산 불가(데이터 부족) — 매도 레이더에서 수동 설정하세요"
        _tp_v = plan.get("target")
        _tp_f = None
        try:
            if _tp_v is not None and pd.notna(_tp_v) and np.isfinite(float(_tp_v)) and float(_tp_v) > 0:
                _tp_f = float(_tp_v)
        except (TypeError, ValueError):
            _tp_f = None
        ok, err = save_portfolio_plan_setting(user_id, account, ticker, float(plan["stop"]), _tp_f)
        if not ok:
            return f" · 📐 플랜 자동 저장 실패: {err}"
        _bits = f" · 📐 플랜 자동 저장: 손절 ${float(plan['stop']):.2f}"
        if _tp_f is not None:
            _bits += f" · 목표 ${_tp_f:.2f}"
        _rr = plan.get("rr_label")
        if _rr and _rr != "-":
            _bits += f" · R:R {_rr}"
        return _bits
    except Exception as exc:
        return f" · 📐 플랜 자동 저장 실패: {exc}"


def save_thesis_row(user_id: str, ticker: str, account: str, thesis_title: str, narrative_category: str, narrative_date: str) -> tuple[bool, str]:
    """Thesis 시트에 한 행 저장."""
