def _fred_api_key() -> str:
    """FRED API 키 — st.secrets 우선 (flat 또는 [fred] 섹션), env 폴백."""
    try:
        v = str(st.secrets.get("FRED_API_KEY", "") or "").strip()
        if v:
            return v
    except Exception:
        pass
    try:
        v = str(st.secrets["fred"]["api_key"]).strip()
        if v:
            return v
    except Exception:
        pass
    import os as _os
    return _os.environ.get("FRED_API_KEY", "").strip()


