def evaluate_cpi_yoy():
    try:
        cpi_series = _fetch_cpi_series()
        if cpi_series.empty:
            return MACRO_STATUS_NA, np.nan, _FRED_TRANSIENT_ERROR_NOTE
        df_cpi = pd.DataFrame({"CPIAUCSL": cpi_series})
        df_cpi["CPIAUCSL"] = pd.to_numeric(df_cpi["CPIAUCSL"], errors="coerce")
        df_cpi = df_cpi.dropna()
        if df_cpi.empty:
            return MACRO_STATUS_NA, np.nan, "CPI 데이터가 비어 있습니다."

        cpi = df_cpi["CPIAUCSL"].sort_index()

        if len(cpi) < 14:
            return MACRO_STATUS_NA, np.nan, "CPI 표본이 부족합니다."

        yoy = float((cpi.iloc[-1] / cpi.iloc[-13] - 1.0) * 100)

        if yoy > 4.8:
            status = MACRO_STATUS_FAIL
            note = "물가 여전히 높은 구간입니다. 장기 높은 금리 레짐 우려가 성장주에 불리합니다."
        elif yoy > 3.2:
            status = MACRO_STATUS_WARN
            note = "연준의 금리·유동성 기조를 주시해야 하는 물가 수준입니다."
        else:
            status = MACRO_STATUS_PASS
            note = "완만한 디스인플레이션에 가까운 구간입니다(휴리스틱)."

        return status, yoy, note
    except Exception:
        return MACRO_STATUS_NA, np.nan, _FRED_TRANSIENT_ERROR_NOTE


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_dxy_latest_and_mean_deviation():
    """DXY 달러 인덱스.
    1순위: FRED DTWEXBGS  2순위: FMP UUP ETF (DXY 추적)
    """
    def _calc(closes_s: pd.Series):
        if closes_s.empty:
            return np.nan, np.nan, MACRO_STATUS_NA
        cur = float(closes_s.iloc[-1])
        ma252 = float(closes_s.rolling(window=252, min_periods=63).mean().iloc[-1])
        if pd.isna(cur) or pd.isna(ma252) or ma252 == 0:
            return cur, np.nan, MACRO_STATUS_NA
        dev_pct = (cur / ma252 - 1.0) * 100
        if dev_pct >= 5.5:
            return cur, dev_pct, MACRO_STATUS_FAIL
        if dev_pct >= 2.5:
            return cur, dev_pct, MACRO_STATUS_WARN
        return cur, dev_pct, MACRO_STATUS_PASS
    # FRED
    try:
        s = fred.get_series("DTWEXBGS")
        s = pd.to_numeric(s, errors="coerce").dropna()
        if not s.empty:
            return _calc(s.tail(400))
    except Exception:
        pass
    # FMP UUP (DXY ETF) — full 엔드포인트
    try:
        k = _fmp_key()
        if k:
            r = requests.get(
                f"{_FMP_BASE}/historical-price-eod/full?symbol=UUP&limit=400&apikey={k}",
                timeout=_FMP_TIMEOUT,
            )
            if r.status_code == 200:
                d = r.json()
                rows = d.get("historical", d) if isinstance(d, dict) else d
                if isinstance(rows, list) and rows:
                    df = pd.DataFrame(rows)
                    if "date" in df.columns:
                        cc = "close" if "close" in df.columns else "Close"
                        df["date"] = pd.to_datetime(df["date"])
                        df = df.set_index("date").sort_index()
                        s = pd.to_numeric(df[cc], errors="coerce").dropna()
                        if not s.empty:
                            return _calc(s)
    except Exception:
        pass
    return np.nan, np.nan, MACRO_STATUS_NA


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_earnings_calendar(tickers: tuple) -> list[dict]:
    """보유 종목의 다음 실적 발표일.

    3-layer fallback 전략 (전부 FMP):
      1) FMP earnings-calendar  (from=오늘, to=오늘+90일, symbol=X)
      2) FMP earnings           (/stable/earnings?symbol=X)
      3) FMP quote              (earningsAnnouncement 필드)
    """
    k = _fmp_key()
    today = datetime.now(_MARKET_ET_TZ).date()  # 시장 기준일 = 미 동부시간
    tomorrow_dt = today + timedelta(days=1)
    from_str = today.strftime("%Y-%m-%d")
    to_str   = (today + timedelta(days=90)).strftime("%Y-%m-%d")
    results  = []

    def _parse_future(items: list, date_key: str = "date") -> tuple:
        """items 리스트에서 내일 이후 가장 이른 (days_until, date_str, item) 반환."""
        future = []
        for it in (items if isinstance(items, list) else []):
            ds = str(it.get(date_key) or "")[:10]
            if not ds or len(ds) < 10:
                continue
            try:
                dt = datetime.strptime(ds, "%Y-%m-%d").date()
                if dt >= tomorrow_dt:
                    future.append(((dt - today).days, ds, it))
            except Exception:
                continue
        return sorted(future)[0] if future else None

    def _parse_ann_field(ann_str: str) -> tuple | None:
        """단순 날짜 문자열(earningsAnnouncement)을 (days, date_str, {}) 형태로 변환."""
        ds = str(ann_str or "")[:10]
        if not ds or len(ds) < 10:
            return None
        try:
            dt = datetime.strptime(ds, "%Y-%m-%d").date()
            if dt >= tomorrow_dt:
                return (dt - today).days, ds, {}
        except Exception:
            pass
        return None

    for tk in tickers:
        best: tuple | None = None
        eps_estimate = None
        try:
            # ── Layer 1: earnings-calendar with date range ────────────────
            if k and best is None:
                try:
                    r = requests.get(
                        f"{_FMP_BASE}/earnings-calendar"
                        f"?symbol={tk}&from={from_str}&to={to_str}&apikey={k}",
                        timeout=_FMP_TIMEOUT,
                    )
                    if r.status_code == 200:
                        data = r.json()
                        found = _parse_future(data if isinstance(data, list) else [])
                        if found:
                            best = found
                            eps_estimate = to_float(found[2].get("epsEstimated"))
                except Exception:
                    pass

            # ── Layer 2: /stable/earnings (includes upcoming) ─────────────
            if k and best is None:
                try:
                    r2 = requests.get(
                        f"{_FMP_BASE}/earnings?symbol={tk}&apikey={k}",
                        timeout=_FMP_TIMEOUT,
                    )
                    if r2.status_code == 200:
                        data2 = r2.json()
                        found2 = _parse_future(data2 if isinstance(data2, list) else [])
                        if found2:
                            best = found2
                            eps_estimate = to_float(found2[2].get("epsEstimated"))
                except Exception:
                    pass

            # ── Layer 3: quote earningsAnnouncement field ─────────────────
            if k and best is None:
                try:
                    rq = requests.get(
                        f"{_FMP_BASE}/quote?symbol={tk}&apikey={k}",
                        timeout=_FMP_TIMEOUT,
                    )
                    if rq.status_code == 200:
                        qd = rq.json()
                        q_item = qd[0] if isinstance(qd, list) and qd else {}
                        ann = str(q_item.get("earningsAnnouncement") or "")[:10]
                        parsed = _parse_ann_field(ann)
                        if parsed:
                            best = parsed
                except Exception:
                    pass

            if best:
                days_until, date_str, _ = best
                results.append({
                    "ticker":        tk,
                    "earnings_date": date_str,
                    "days_until":    days_until,
                    "eps_estimate":  eps_estimate,
                })
        except Exception:
            continue

    results.sort(key=lambda x: x["days_until"])
    return results


@st.cache_data(ttl=3600, show_spinner=False)
def _earnings_cal_one(ticker: str) -> dict | None:
    """종목 1개짜리 캐시 단위. 위 함수를 그대로 재사용한다."""
    r = fetch_earnings_calendar((str(ticker).strip().upper(),))
    return r[0] if r else None


def fetch_earnings_calendar_smart(tickers: tuple) -> list[dict]:
    """종목별로 캐시된 결과를 모아 돌려준다.

    ⚠️ 왜 이렇게 바꿨나
       fetch_earnings_calendar 는 **티커 튜플 전체가 캐시 키**다. 그래서 매도
       레이더에서 계좌 필터를 하나 켜고 끌 때마다 티커 집합이 달라져 캐시가
       통째로 미스되고, 종목당 최대 3콜(3단 폴백)을 전부 다시 받았다.
       종목 단위로 쪼개면 **새로 들어온 종목만** 조회한다. 필터를 되돌리면 0콜이다.

    정렬은 여기서 다시 한다 — 종목별 캐시에는 순서 정보가 없다.
    """
    out = []
    for _t in tickers:
        try:
            _r = _earnings_cal_one(_t)
        except Exception:
            _r = None
        if _r:
            out.append(_r)
    out.sort(key=lambda x: x.get("days_until", 9999))
    return out


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_fed_funds_rate() -> tuple[float, str]:
    """현재 기준금리.
    1순위: FRED FEDFUNDS  2순위: FMP federalFundsRate
    """
    def _fed_note(rate: float) -> str:
        if rate >= 5.0:
            return "고금리 레짐. 성장주 밸류에이션 압박 지속."
        if rate >= 3.0:
            return "중립 이상 금리. 연준 기조 모니터링 필요."
        return "완화적 금리 환경. 유동성 우호적."
    # FRED
    try:
        series = fred.get_series("FEDFUNDS")
        if series is not None and not series.empty:
            rate = float(pd.to_numeric(series, errors="coerce").dropna().iloc[-1])
            if pd.notna(rate):
                return rate, _fed_note(rate)
    except Exception:
        pass
    # FMP federalFundsRate
    try:
        k = _fmp_key()
        if k:
            r = requests.get(
                f"{_FMP_BASE}/economic-indicators?name=federalFundsRate&apikey={k}",
                timeout=_FMP_TIMEOUT,
            )
            if r.status_code == 200:
                data = r.json()
                if isinstance(data, list) and data:
                    rate = to_float(data[0].get("value"))
                    if pd.notna(rate):
                        return rate, _fed_note(rate) + " [FMP]"
    except Exception:
        pass
    return np.nan, _FRED_TRANSIENT_ERROR_NOTE


def _hist_fetch_fedfunds() -> pd.Series:
    """FEDFUNDS 히스토리 — FRED 1순위, FMP 폴백."""
    try:
        s = fred.get_series("FEDFUNDS")
        if s is not None and not s.empty:
            return pd.to_numeric(s, errors="coerce").dropna().tail(24)
    except Exception:
        pass
    try:
        k = _fmp_key()
        if k:
            r = requests.get(
                f"{_FMP_BASE}/economic-indicators?name=federalFundsRate&apikey={k}",
                timeout=_FMP_TIMEOUT,
            )
            if r.status_code == 200:
                data = r.json()
                if isinstance(data, list) and data:
                    df = pd.DataFrame(data)[["date", "value"]].copy()
                    df["date"] = pd.to_datetime(df["date"])
                    df = df.set_index("date").sort_index()
                    return pd.to_numeric(df["value"], errors="coerce").dropna().tail(24)
    except Exception:
        pass
    return pd.Series(dtype=float)


def _hist_fetch_dxy() -> pd.Series:
    """DXY 히스토리 — FRED 1순위, FMP UUP 폴백."""
    try:
        s = fred.get_series("DTWEXBGS")
        if s is not None and not s.empty:
            return pd.to_numeric(s, errors="coerce").dropna().tail(500)
    except Exception:
        pass
    try:
        k = _fmp_key()
        if k:
            r = requests.get(
                f"{_FMP_BASE}/historical-price-eod/full?symbol=UUP&limit=500&apikey={k}",
                timeout=_FMP_TIMEOUT,
            )
            if r.status_code == 200:
                d = r.json()
                rows = d.get("historical", d) if isinstance(d, dict) else d
                if isinstance(rows, list) and rows:
                    df = pd.DataFrame(rows)
                    if "date" in df.columns:
                        cc = "close" if "close" in df.columns else "Close"
                        df["date"] = pd.to_datetime(df["date"])
                        df = df.set_index("date").sort_index()
                        return pd.to_numeric(df[cc], errors="coerce").dropna().tail(500)
    except Exception:
        pass
    return pd.Series(dtype=float)


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_macro_history_series() -> dict:
    """CPI·실업률·DXY·Fed Rate 1~2년 히스토리 시리즈.
    4개 소스를 ThreadPoolExecutor로 병렬 조회.
    """
    import concurrent.futures as _cf

    def _safe_cpi():
        try:
            s = _fetch_cpi_series()
            if not s.empty:
                df = pd.DataFrame({"CPI": s}).dropna()
                df["v"] = df["CPI"].pct_change(12) * 100
                return ("cpi", df["v"].dropna().tail(24))
        except Exception:
            pass
        return ("cpi", pd.Series(dtype=float))

    def _safe_un():
        try:
            s = _fetch_unrate_series()
            if not s.empty:
                return ("unrate", s.tail(24))
        except Exception:
            pass
        return ("unrate", pd.Series(dtype=float))

    def _safe_fed():
        return ("fedfunds", _hist_fetch_fedfunds())

    def _safe_dxy():
        return ("dxy", _hist_fetch_dxy())

    out = {}
    with _cf.ThreadPoolExecutor(max_workers=4) as exe:
        futs = [exe.submit(fn) for fn in (_safe_cpi, _safe_un, _safe_fed, _safe_dxy)]
        for fut in _cf.as_completed(futs, timeout=20):
            try:
                key, val = fut.result()
                if not val.empty:
                    out[key] = val
            except Exception:
                pass
    return out


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_fmp_economic_indicator(name: str) -> tuple[float, float, str]:
    """FMP Economic Indicators API — (latest_val, prev_val, date_str).
    name 예: 'GDP', 'retailSales', 'unemploymentRate', 'consumerConfidence'
    """
    k = _fmp_key()
    if not k:
        return np.nan, np.nan, ""
    try:
        r = requests.get(
            f"{_FMP_BASE}/economic-indicators?name={name}&apikey={k}",
            timeout=_FMP_TIMEOUT,
        )
        if r.status_code != 200:
            return np.nan, np.nan, ""
        data = r.json()
        if not isinstance(data, list) or not data:
            return np.nan, np.nan, ""
        latest_val = to_float(data[0].get("value"))
        prev_val = to_float(data[1].get("value")) if len(data) > 1 else np.nan
        date_str = str(data[0].get("date", ""))[:10]
        return latest_val, prev_val, date_str
    except Exception:
        return np.nan, np.nan, ""


@st.cache_data(ttl=3600, show_spinner=False)
def fetch_fmp_market_risk_premium() -> tuple[float, str]:
    """FMP Market Risk Premium API — (US ERP %, note)."""
    k = _fmp_key()
    if not k:
        return np.nan, "FMP API 키 없음"
    try:
        r = requests.get(
            f"{_FMP_BASE}/market-risk-premium?apikey={k}",
            timeout=_FMP_TIMEOUT,
        )
        if r.status_code != 200:
            return np.nan, "데이터 없음"
        data = r.json()
        if not isinstance(data, list) or not data:
            return np.nan, "데이터 없음"
        # US 항목 우선, 없으면 첫 번째
        us_item = next(
            (d for d in data if str(d.get("country", "")).upper() in ("US", "UNITED STATES", "USA")),
            data[0],
        )
        erp = to_float(us_item.get("totalEquityRiskPremium") or us_item.get("equityRiskPremium"))
        country = str(us_item.get("country", "US"))
        if pd.isna(erp):
            return np.nan, "데이터 없음"
        if erp >= 6.0:
            note = f"ERP {erp:.2f}% — 주식이 채권 대비 매우 매력적. 밸류에이션 저평가 구간."
        elif erp >= 4.0:
            note = f"ERP {erp:.2f}% — 주식 위험 프리미엄 적정 구간."
        else:
            note = f"ERP {erp:.2f}% — 주식 프리미엄 낮음. 채권 대비 주식 매력 저하."
        return erp, note
    except Exception:
        return np.nan, "조회 오류"


@st.cache_data(ttl=1800, show_spinner=False)
def fetch_fmp_economic_calendar_risk() -> tuple[list, bool]:
    """FMP Economic Calendar — 지난 2일~향후 3일 US 이벤트 감지.
    조회 창은 발표 직후(actual 확인)와 사전 경고를 함께 보기 위해 today-2 ~ today+3로 둔다.
    각 이벤트에 is_past(과거 발표 여부)를 태깅한다.
    반환: (events_list, has_high_impact)
      - events_list: [{"date","event","impact","actual","estimate","prior","is_past"}]
      - has_high_impact: **향후(오늘 포함) 고임팩트 이벤트만** 카운트(지난 발표는 더 이상 리스크 아님)
    """
    k = _fmp_key()
    if not k:
        return [], False
    try:
        today = datetime.now(_MARKET_ET_TZ).date()  # 시장 기준일 = 미 동부시간
        from_date = (today - timedelta(days=2)).strftime("%Y-%m-%d")
        to_date = (today + timedelta(days=3)).strftime("%Y-%m-%d")
        r = requests.get(
            f"{_FMP_BASE}/economic-calendar?from={from_date}&to={to_date}&apikey={k}",
            timeout=_FMP_TIMEOUT,
        )
        if r.status_code != 200:
            return [], False
        data = r.json()
        if not isinstance(data, list):
            return [], False
        events = []
        for ev in data:
            country = str(ev.get("country", "")).upper()
            if country not in ("US", "USD", "UNITED STATES", ""):
                continue
            impact = str(ev.get("impact", "") or ev.get("importance", "") or "").capitalize()
            event_name = str(ev.get("event", "") or ev.get("name", ""))
            if not event_name:
                continue
            date_str = str(ev.get("date", ""))[:10]
            actual_val = ev.get("actual")
            has_actual = actual_val is not None and str(actual_val).strip() not in ("", "None")
            # 발표완료 판정: 날짜가 오늘 이전이거나, 이미 actual 값이 채워졌으면 발표완료.
            # (actual이 있으면 ET 날짜경계와 무관하게 '발표 끝남'이 확실하다)
            is_past = False
            try:
                if date_str and datetime.strptime(date_str, "%Y-%m-%d").date() < today:
                    is_past = True
            except Exception:
                is_past = False
            if has_actual:
                is_past = True
            events.append({
                "date":     date_str,
                "event":    event_name,
                "impact":   impact,
                "actual":   actual_val,
                "estimate": ev.get("estimate"),
                "prior":    ev.get("previous") or ev.get("prior"),
                "is_past":  is_past,
            })
        # 정렬: 날짜 오름차순(과거 → 오늘 → 미래)
        events.sort(key=lambda e: e.get("date", ""))
        # 리스크 플래그는 '아직 발표되지 않은(오늘 포함)' 고임팩트만 카운트
        has_high = any(
            (not e["is_past"]) and e["impact"].lower() in ("high", "3")
            for e in events
        )
        return events, has_high
    except Exception:
        return [], False


def compute_macro_score(rows: list) -> tuple[float, str, str]:
    """
    6대 지표 + Fear&Greed + Fed Rate를 종합해 0~100 Macro Score 계산.
    반환: (score, grade, description)
    pass=100, warning=50, fail=0, na=50(중립)으로 환산 후 평균.
    """
    score_map = {MACRO_STATUS_PASS: 100, MACRO_STATUS_WARN: 40, MACRO_STATUS_FAIL: 0, MACRO_STATUS_NA: 50}
    scores = [score_map.get(r["_status"], 50) for r in rows]
    if not scores:
        return 50.0, "N/A", "데이터 없음"
    avg = float(np.mean(scores))
    if avg >= 75:
        grade, desc = "🟢 BULLISH", "매크로 환경 우호적. 적극적 포지션 가능."
    elif avg >= 50:
        grade, desc = "🟡 NEUTRAL", "혼재된 신호. 선별적 접근 권장."
    elif avg >= 25:
        grade, desc = "🟠 CAUTIOUS", "위험 신호 누적. 비중 축소 고려."
    else:
        grade, desc = "🔴 BEARISH", "전방위 경고. 현금 비중 확대 권장."
    return avg, grade, desc


def analyze_us_macro_dashboard():
    import concurrent.futures as _cf

    # ── 모든 외부 API를 병렬로 동시 호출 (순차 3분 → 병렬 ~20초) ─────────
    def _safe(fn, *args, **kwargs):
        try:
            return fn(*args, **kwargs)
        except Exception:
            return None

    _tasks = {
        "spread":   (fetch_yield_spread_latest,          []),
        "vix":      (fetch_vix_latest_and_history,       []),
        "wti":      (fetch_wti_latest,                   []),
        "un":       (evaluate_unemployment_sahm_series,  []),
        "cpi":      (evaluate_cpi_yoy,                   []),
        "dxy":      (fetch_dxy_latest_and_mean_deviation,[]),
        "fed":      (fetch_fed_funds_rate,               []),
        "fg":       (fetch_macro_history_series,         []),
        "gdp":      (fetch_fmp_economic_indicator,       ["GDP"]),
        "rs":       (fetch_fmp_economic_indicator,       ["retailSales"]),
        "erp":      (fetch_fmp_market_risk_premium,      []),
    }

    _results = {}
    with _cf.ThreadPoolExecutor(max_workers=11) as _exe:
        _futures = {
            name: _exe.submit(_safe, fn, *args)
            for name, (fn, args) in _tasks.items()
        }
        for name, fut in _futures.items():
            try:
                _results[name] = fut.result(timeout=25)
            except Exception:
                _results[name] = None

    # ── 결과 언팩 ─────────────────────────────────────────────────────
    _s = _results.get("spread") or (np.nan, MACRO_STATUS_NA, "조회 실패")
    spread_val, spread_st, spread_note = _s

    _v = _results.get("vix") or (np.nan, None, "조회 실패")
    vix_val, vix_hist, vix_err = _v
    vix_st, vix_note = evaluate_vix_status(vix_val)

    wti = _results.get("wti") or np.nan
    if wti is None:
        wti = np.nan
    wti_st, wti_note = evaluate_wti_status(wti)

    _u = _results.get("un") or (MACRO_STATUS_NA, np.nan, np.nan, np.nan, _FRED_TRANSIENT_ERROR_NOTE)
    un_st, un_avg3, un_yr_low, un_margin, un_note = _u

    _c = _results.get("cpi") or (MACRO_STATUS_NA, np.nan, _FRED_TRANSIENT_ERROR_NOTE)
    cpi_st, cpi_yoy, cpi_note = _c

    _d = _results.get("dxy") or (np.nan, np.nan, MACRO_STATUS_NA)
    dxy, dxy_dev, dxy_st_base = _d

    rows = []

    rows.append(
        {
            "지표": "장단기 금리차 (10Y-3M)",
            "현재값": f"{spread_val:.2f} pp (10Y TNX − 3M IRX)" if pd.notna(spread_val) else "N/A",
            "판정": macro_status_label(spread_st),
            "판독 요약": spread_note,
            "_status": spread_st,
        }
    )

    rows.append(
        {
            "지표": "VIX (공포 지수)",
            "현재값": num_str(vix_val),
            "판정": macro_status_label(vix_st),
            "판독 요약": vix_note + ("" if (not vix_err or vix_err in ("FMP폴백", "None", None)) else f" [{vix_err}]"),
            "_status": vix_st,
        }
    )

    rows.append(
        {
            "지표": "WTI 원유 ($/BBL)",
            "현재값": num_str(wti),
            "판정": macro_status_label(wti_st),
            "판독 요약": wti_note,
            "_status": wti_st,
        }
    )

    if pd.notna(un_avg3) and pd.notna(un_yr_low) and pd.notna(un_margin):
        un_display = (
            f"3M평균 {un_avg3:.2f}% · 12M최저 {un_yr_low:.2f}% · Δ +{un_margin:.2f} pp"
        )
    elif pd.notna(un_avg3) or pd.notna(un_yr_low):
        un_display = f"Avg/min: {num_str(un_avg3)} / {num_str(un_yr_low)}"
    else:
        un_display = "N/A"
    rows.append(
        {
            "지표": "실업률 UNRATE (샴 근접)",
            "현재값": "N/A" if un_note == _FRED_TRANSIENT_ERROR_NOTE else un_display,
            "판정": macro_status_label(un_st),
            "판독 요약": un_note,
            "_status": un_st,
        }
    )

    rows.append(
        {
            "지표": "CPI 전년 동월 대비 (YoY)",
            "현재값": "N/A" if cpi_note == _FRED_TRANSIENT_ERROR_NOTE else (pct_points_str(cpi_yoy) if pd.notna(cpi_yoy) else "N/A"),
            "판정": macro_status_label(cpi_st),
            "판독 요약": cpi_note if isinstance(cpi_note, str) else str(cpi_note),
            "_status": cpi_st,
        }
    )

    dxy_disp = (
        f"{num_str(dxy)} (vs MA252 편차 {pct_points_str(dxy_dev)})"
        if pd.notna(dxy) and pd.notna(dxy_dev)
        else num_str(dxy)
    )
    rows.append(
        {
            "지표": "달러 지수 DXY",
            "현재값": dxy_disp,
            "판정": macro_status_label(dxy_st_base),
            "판독 요약": (
                "252거래일 대비 과도한 달러 강세 가능성입니다. 다국적 빅테크 환차익 우려."
                if dxy_st_base == MACRO_STATUS_FAIL
                else (
                    "달러 중간적으로 강한 편입니다. 실적 번역 노이즈 확인."
                    if dxy_st_base == MACRO_STATUS_WARN
                    else (
                        "달러가 극단적 강세권이라고 보기 어렵습니다."
                        if dxy_st_base == MACRO_STATUS_PASS
                        else "데이터 부족 (N/A)."
                    )
                )
            ),
            "_status": dxy_st_base,
        }
    )

    # Market Sentiment Score — VIX 데이터 직접 인라인 계산 (별도 API 호출 없음)
    fg_score = np.nan
    fg_rating = "N/A"
    fg_status = MACRO_STATUS_NA
    try:
        if vix_hist is not None and not vix_hist.empty and "Close" in vix_hist.columns:
            _vix_s = pd.to_numeric(vix_hist["Close"], errors="coerce").dropna()
            if len(_vix_s) >= 20 and pd.notna(vix_val):
                # VIX 백분위 역산 → 낮을수록 탐욕
                _vix_pct = float((_vix_s < float(vix_val)).sum() / len(_vix_s) * 100)
                fg_score = float(np.clip(100.0 - _vix_pct, 0, 100))
                if fg_score >= 75:
                    fg_rating, fg_status = "Extreme Greed", MACRO_STATUS_FAIL
                elif fg_score >= 55:
                    fg_rating, fg_status = "Greed", MACRO_STATUS_WARN
                elif fg_score >= 45:
                    fg_rating, fg_status = "Neutral", MACRO_STATUS_PASS
                elif fg_score >= 25:
                    fg_rating, fg_status = "Fear", MACRO_STATUS_PASS
                else:
                    fg_rating, fg_status = "Extreme Fear", MACRO_STATUS_PASS
    except Exception:
        pass
    rows.append({
        "지표": "Market Sentiment (VIX 기반)",
        "현재값": f"{fg_score:.0f} / 100 ({fg_rating})" if pd.notna(fg_score) else "N/A",
        "판정": macro_status_label(fg_status),
        "판독 요약": (
            "극단적 탐욕 구간. 과매수 경고, 조정 가능성 높음." if pd.notna(fg_score) and fg_score >= 75
            else "탐욕 구간. 추격 매수 주의." if pd.notna(fg_score) and fg_score >= 55
            else "극단적 공포 구간. 역발상 매수 기회일 수 있습니다." if pd.notna(fg_score) and fg_score <= 25
            else "중립~공포 구간. 시장 심리 정상화 중." if pd.notna(fg_score)
            else "VIX 데이터 부족."
        ),
        "_status": fg_status,
    })

    # Fed Funds Rate
    _fr = _results.get("fed") or (np.nan, _FRED_TRANSIENT_ERROR_NOTE)
    fed_rate, fed_note = _fr
    fed_status = (
        MACRO_STATUS_FAIL if pd.notna(fed_rate) and fed_rate >= 5.0
        else MACRO_STATUS_WARN if pd.notna(fed_rate) and fed_rate >= 3.0
        else MACRO_STATUS_PASS if pd.notna(fed_rate)
        else MACRO_STATUS_NA
    )
    rows.append({
        "지표": "연준 기준금리 (Fed Funds Rate)",
        "현재값": f"{fed_rate:.2f}%" if pd.notna(fed_rate) else "N/A",
        "판정": macro_status_label(fed_status),
        "판독 요약": fed_note,
        "_status": fed_status,
    })

    # ── FMP GDP 성장률 (QoQ %) ──────────────────────────────────────────
    # FMP 'GDP' API는 절대값(십억 달러 단위 연율)을 반환하므로
    # 전분기 대비 변화율(%)을 직접 계산해야 한다.
    _gdp = _results.get("gdp") or (np.nan, np.nan, "")
    gdp_abs, gdp_abs_prev, gdp_date = _gdp
    if pd.notna(gdp_abs) and pd.notna(gdp_abs_prev) and gdp_abs_prev != 0:
        gdp_qoq = float((gdp_abs / gdp_abs_prev - 1.0) * 100)
    else:
        gdp_qoq = np.nan

    if pd.notna(gdp_qoq):
        if gdp_qoq < 0:
            gdp_st = MACRO_STATUS_FAIL
            gdp_note = f"GDP QoQ {gdp_qoq:+.2f}% ({gdp_date}) — 마이너스 성장, 기술적 침체 위험 구간."
        elif gdp_qoq < 0.5:
            gdp_st = MACRO_STATUS_WARN
            gdp_note = f"GDP QoQ {gdp_qoq:+.2f}% ({gdp_date}) — 성장 정체 구간. 경기 모멘텀 약화 신호."
        elif gdp_qoq < 1.0:
            gdp_st = MACRO_STATUS_WARN
            gdp_note = f"GDP QoQ {gdp_qoq:+.2f}% ({gdp_date}) — 저성장 구간. 선별적 접근 필요."
        else:
            gdp_st = MACRO_STATUS_PASS
            gdp_note = f"GDP QoQ {gdp_qoq:+.2f}% ({gdp_date}) — 실물 경기 안정권."
        gdp_display = f"{gdp_qoq:+.2f}% (QoQ)"
    elif pd.notna(gdp_abs):
        # prev 없이 절대값만 있을 때 — 표시만 하고 NA 판정
        gdp_st = MACRO_STATUS_NA
        gdp_note = f"GDP 절대값 ${gdp_abs:,.0f}B ({gdp_date}). 전분기 데이터 없어 성장률 계산 불가."
        gdp_display = f"${gdp_abs:,.0f}B"
    else:
        gdp_st = MACRO_STATUS_NA
        gdp_note = "GDP 데이터 없음 (FMP 조회 실패 또는 API 키 미설정)."
        gdp_display = "N/A"

    rows.append({
        "지표": "GDP 성장률 QoQ (FMP)",
        "현재값": gdp_display,
        "판정": macro_status_label(gdp_st),
        "판독 요약": gdp_note,
        "_status": gdp_st,
    })

    # ── FMP Retail Sales (소매판매 MoM %) ──────────────────────────────
    # FMP 'retailSales' API는 절대값(백만 달러)을 반환하므로
    # 전월 대비 변화율(%)을 직접 계산해야 한다.
    _rs = _results.get("rs") or (np.nan, np.nan, "")
    rs_abs, rs_abs_prev, rs_date = _rs
    if pd.notna(rs_abs) and pd.notna(rs_abs_prev) and rs_abs_prev != 0:
        rs_mom = float((rs_abs / rs_abs_prev - 1.0) * 100)
    else:
        rs_mom = np.nan

    if pd.notna(rs_mom):
        if rs_mom < -1.0:
            rs_st = MACRO_STATUS_FAIL
            rs_note = f"소매판매 MoM {rs_mom:+.2f}% ({rs_date}) — 소비 급감, 경기 침체 우려."
        elif rs_mom < 0:
            rs_st = MACRO_STATUS_WARN
            rs_note = f"소매판매 MoM {rs_mom:+.2f}% ({rs_date}) — 소비 모멘텀 둔화."
        elif rs_mom < 0.3:
            rs_st = MACRO_STATUS_WARN
            rs_note = f"소매판매 MoM {rs_mom:+.2f}% ({rs_date}) — 소비 정체 구간. 모니터링 필요."
        else:
            rs_st = MACRO_STATUS_PASS
            rs_note = f"소매판매 MoM {rs_mom:+.2f}% ({rs_date}) — 소비 체력 유지."
        rs_display = f"{rs_mom:+.2f}% (MoM)"
    elif pd.notna(rs_abs):
        rs_st = MACRO_STATUS_NA
        rs_note = f"소매판매 절대값 ${rs_abs:,.0f}M ({rs_date}). 전월 데이터 없어 변화율 계산 불가."
        rs_display = f"${rs_abs:,.0f}M"
    else:
        rs_st = MACRO_STATUS_NA
        rs_note = "소매판매 데이터 없음."
        rs_display = "N/A"

    rows.append({
        "지표": "소매판매 MoM (FMP)",
        "현재값": rs_display,
        "판정": macro_status_label(rs_st),
        "판독 요약": rs_note,
        "_status": rs_st,
    })

    # ── FMP Market Risk Premium (ERP) ──────────────────────────────────
    _erp = _results.get("erp") or (np.nan, "조회 실패")
    erp_val, erp_note = _erp
    if pd.notna(erp_val):
        if erp_val >= 5.5:
            erp_st = MACRO_STATUS_PASS
        elif erp_val >= 3.5:
            erp_st = MACRO_STATUS_WARN
        else:
            erp_st = MACRO_STATUS_FAIL
    else:
        erp_st = MACRO_STATUS_NA
    rows.append({
        "지표": "주식 위험 프리미엄 ERP (FMP)",
        "현재값": f"{erp_val:.2f}%" if pd.notna(erp_val) else "N/A",
        "판정": macro_status_label(erp_st),
        "판독 요약": erp_note,
        "_status": erp_st,
    })

    bad_total = sum(1 for r in rows if macro_status_bad_count(r["_status"]))
    na_total = sum(1 for r in rows if r["_status"] == MACRO_STATUS_NA)
    macro_score, macro_grade, macro_desc = compute_macro_score(rows)

    return {
        "rows": rows,
        "bad_total": bad_total,
        "vix_hist": vix_hist,
        "spread_val": spread_val,
        "vix_val": vix_val,
        "na_total": na_total,
        "macro_score": macro_score,
        "macro_grade": macro_grade,
        "macro_desc": macro_desc,
        "fg_score": fg_score,
        "fg_rating": fg_rating,
        "fed_rate": fed_rate,
    }






def hidden_alpha_horizon_returns(close_series):
    """
    Trading-day horizons for Hidden Alpha: 5 / 10 / 21 / 63 over daily closes.
    """
    return {
        "1주(%)": calculate_period_return(close_series, 5),
        "2주(%)": calculate_period_return(close_series, 10),
        "1개월(%)": calculate_period_return(close_series, 21),
        "3개월(%)": calculate_period_return(close_series, 63),
    }


def get_close_prices_from_download(download_df):
    """
    Normalize price-download output to a close-price DataFrame with ticker columns.
    """
    if download_df is None or download_df.empty:
        return pd.DataFrame()

    if isinstance(download_df.columns, pd.MultiIndex):
        if "Close" in download_df.columns.get_level_values(0):
            close_df = download_df["Close"].copy()
        elif "Adj Close" in download_df.columns.get_level_values(0):
            close_df = download_df["Adj Close"].copy()
        else:
            return pd.DataFrame()
    else:
        # Single ticker fallback
        if "Close" in download_df.columns:
            close_df = download_df[["Close"]].copy()
            close_df.columns = ["SINGLE"]
        elif "Adj Close" in download_df.columns:
            close_df = download_df[["Adj Close"]].copy()
            close_df.columns = ["SINGLE"]
        else:
            return pd.DataFrame()

    return close_df


def build_sector_returns_table(close_df, sector_etfs):
    records = []
    for ticker, sector_name in sector_etfs:
        series = close_df[ticker] if ticker in close_df.columns else pd.Series(dtype=float)
        records.append(
            {
                "Ticker": ticker,
                "Sector": sector_name,
                "1-Week (%)": calculate_period_return(series, 5),
                "1-Month (%)": calculate_period_return(series, 21),
                "3-Month (%)": calculate_period_return(series, 63),
                "6-Month (%)": calculate_period_return(series, 126),
                "1-Year (%)": calculate_period_return(series, 252),
            }
        )
    ordered_cols = [
        "Sector",
        "Ticker",
        "1-Week (%)",
        "1-Month (%)",
        "3-Month (%)",
        "6-Month (%)",
        "1-Year (%)",
    ]
    return pd.DataFrame(records)[ordered_cols]


def build_etf_universe_returns_table(pool_tickers):
    """
    유니버스 티커별 수익률을 한 번에 계산한다. 신규 ETF 등 과거 일부 구간이 비어도 티커 행은 유지한다(NaN).
    """
    cols = ["Ticker", "1주(%)", "2주(%)", "1개월(%)", "3개월(%)", "1-Month (%)"]
    if not pool_tickers:
        return pd.DataFrame(columns=cols)

    unique_tickers = list(
        dict.fromkeys(str(t).strip().upper() for t in pool_tickers if str(t).strip())
    )
    if not unique_tickers:
        return pd.DataFrame(columns=cols)

    try:
        close_df = _fmp_batch_to_close_df(unique_tickers, limit=130)
    except Exception:
        close_df = pd.DataFrame()

    if close_df.empty:
        rows = [
            {"Ticker": t, "1주(%)": np.nan, "2주(%)": np.nan, "1개월(%)": np.nan, "3개월(%)": np.nan, "1-Month (%)": np.nan}
            for t in unique_tickers
        ]
        return pd.DataFrame(rows)

    if len(unique_tickers) == 1 and "SINGLE" in close_df.columns:
        close_df = close_df.copy()
        close_df.columns = [unique_tickers[0]]

    rows = []
    for ticker in unique_tickers:
        series = close_df[ticker] if ticker in close_df.columns else pd.Series(dtype=float)
        h = hidden_alpha_horizon_returns(series)
        one_m = h["1개월(%)"]
        rows.append(
            {
                "Ticker": ticker,
                "1주(%)": h["1주(%)"],
                "2주(%)": h["2주(%)"],
                "1개월(%)": one_m,
                "3개월(%)": h["3개월(%)"],
                "1-Month (%)": one_m,
            }
        )

    result_df = pd.DataFrame(rows)
    for c in ("1주(%)", "2주(%)", "1개월(%)", "3개월(%)", "1-Month (%)"):
        result_df[c] = pd.to_numeric(result_df[c], errors="coerce")
    return result_df


_RS_SCAN_MISS_REASONS = {
    "no_data":   "데이터 없음 — 상장폐지/티커 변경 추정 · ETF Universe 정리 대상",
    "exhausted": "재시도 소진 — FMP 일시 장애 (재스캔 권장)",
    "no_key":    "FMP API 키 미설정",
    "short":     "히스토리 70거래일 미만 — 신규 상장 (RS 계산 불가)",
}


_RS_INCUBATOR_SHEET_TITLE = "RS_Incubator"
_RS_INCUBATOR_COLS = ["Ticker", "Bars_Seen", "Observed_Date"]
_RS_MIN_BARS = 70  # RS 계산 최소 거래일


def _open_rs_incubator_ws():
    """Quant_DB의 RS_Incubator 탭 (없으면 생성).
    스캔이 직접 관측한 '히스토리 부족' 티커의 봉 수를 기억 — 졸업 예상 시점까지 재fetch 를 건너뛴다.
    (Added_Date 추정 방식은 유니버스 일괄 시드 시 전 종목이 같은 날짜가 되어 폐기 — 관측 기반이 정답)"""
    gc = get_gspread_client()
    if gc is None:
        return None, "Google 서비스 계정이 설정되지 않았습니다."
    try:
        _ws_c = _ws_handle(_RS_INCUBATOR_SHEET_TITLE)
        if _ws_c is not None:
            return _ws_c, None
        sh = _open_quant_db()
        ws = sh.add_worksheet(title=_RS_INCUBATOR_SHEET_TITLE, rows=1000, cols=3)
        ws.update([_RS_INCUBATOR_COLS], range_name="A1:C1", value_input_option="USER_ENTERED")
        _invalidate_ws_handles()
        return ws, None
    except Exception as exc:
        return None, f"RS_Incubator 워크시트 열기/생성 실패: {exc}"


@st.cache_data(ttl=600, show_spinner=False)
def load_rs_incubator_map() -> dict:
    """{Ticker: (bars_seen:int, observed_date:date)} — 관측 기록 로드."""
    try:
        ws, err = _open_rs_incubator_ws()
        if err or ws is None:
            return {}
        vals = ws.get_all_values() or []
    except Exception:
        return {}
    out = {}
    for r in vals[1:]:
        if len(r) < 3:
            continue
        tk = str(r[0]).strip().upper()
        try:
            bars = int(float(str(r[1]).strip()))
            obs = datetime.strptime(str(r[2]).strip()[:10], "%Y-%m-%d").date()
        except Exception:
            continue
        if tk:
            out[tk] = (bars, obs)
    return out


def split_incubator_tickers(tickers: list):
    """🐣 인큐베이터 v2 (관측 기반) — 지난 스캔에서 실측된 봉 수 + 경과 시간으로
    현재 예상 봉 수를 추정, 70거래일 미달 예상 티커는 fetch 없이 사전 분리.

    예상 봉 수 = 관측 봉 수 + 경과일 × 5/7 (거래일 환산). 예상치가 70에 도달하면
    자동으로 스캔에 재편입(졸업 시도) — 실제로 아직 부족하면 재관측되어 자기 보정된다.
    첫 스캔(기록 없음)은 전체 fetch 후 부족 티커가 기록되는 부트스트랩.
    반환: (eligible, incubator)"""
    syms = [str(t).strip().upper() for t in (tickers or []) if str(t).strip()]
    if not syms:
        return [], []
    try:
        obs_map = load_rs_incubator_map()
    except Exception:
        obs_map = {}
    if not obs_map:
        return syms, []
    today = datetime.now(_MARKET_ET_TZ).date()
    eligible, incubator = [], []
    for tk in syms:
        rec = obs_map.get(tk)
        if rec is None:
            eligible.append(tk)
            continue
        bars, obs = rec
        est = bars + int(max(0, (today - obs).days) * 5 / 7)
        (incubator if est < _RS_MIN_BARS else eligible).append(tk)
    return eligible, incubator


def update_rs_incubator_observations(report: dict, ok_tickers) -> None:
    """스캔 결과로 관측 기록 갱신 (비차단 — 실패해도 스캔 표시에 영향 없음).
    - 이번 스캔에서 '히스토리 부족'으로 실측된 티커 → 봉 수와 함께 upsert
    - 이번 스캔에서 정상 계산된 티커(졸업) → 기록 제거
    - 이번 스캔에서 건너뛴(인큐베이터) 티커 → 기존 기록 유지"""
    try:
        prev = dict(load_rs_incubator_map())
        ok_set = {str(t).strip().upper() for t in (ok_tickers or [])}
        today_str = datetime.now(_MARKET_ET_TZ).strftime("%Y-%m-%d")
        changed = False
        for m in (report or {}).get("missing", []):
            if m.get("reason_key") == "short" and m.get("bars") is not None:
                prev[str(m["ticker"]).strip().upper()] = (int(m["bars"]), None)  # None → 오늘로 기록
                changed = True
        graduated = [tk for tk in list(prev.keys()) if tk in ok_set]
        for tk in graduated:
            prev.pop(tk, None)
            changed = True
        if not changed:
            return
        ws, err = _open_rs_incubator_ws()
        if err or ws is None:
            return
        rows = [_RS_INCUBATOR_COLS] + [
            [tk, str(bars), (obs.strftime("%Y-%m-%d") if obs is not None else today_str)]
            for tk, (bars, obs) in sorted(prev.items())
        ]
        ws.clear()
        ws.update(rows, range_name=f"A1:C{len(rows)}", value_input_option="USER_ENTERED")
        load_rs_incubator_map.clear()
    except Exception:
        pass


@st.cache_data(ttl=3600, show_spinner=False)
def cached_satellite_top10() -> dict:
    """🛰️ 위성 섹터 Top10 — SSOT 는 fmp_extras.compute_satellite_top10 (주간 이메일과 동일 로직).
    탭 진입 시 자동 계산 · 1시간 캐시 (버튼 불필요)."""
    return fx.compute_satellite_top10()


def render_scan_coverage_report(report: dict) -> None:
    """RS 스캔(Early Signal·섹터 꺾임) 커버리지 + 미수집 사유 렌더링.
    '전수 fetch + 투명 보고' 원칙: 311개면 311개 전부에 대해 답이 있거나, 왜 없는지 보여준다."""
    if not report:
        return
    total = int(report.get("total") or 0)
    missing = report.get("missing") or []
    incubator = report.get("incubator") or []
    covered = total - len(missing)
    if total <= 0 and not incubator:
        return
    _inc_note = (
        f" · 🐣 인큐베이터 **{len(incubator)}개**" if incubator else ""
    )
    if not missing:
        st.caption(f"✅ 커버리지 **{covered}/{total}** — 전수 수집 완료{_inc_note}")
    else:
        st.caption(f"커버리지 **{covered}/{total}** · ⚠️ 미수집 {len(missing)}개 (아래 사유 확인){_inc_note}")
    if incubator:
        with st.expander(f"🐣 인큐베이터 {len(incubator)}개 — 히스토리 70거래일 미달 관측 (도달 예상 시점에 자동 재편입)", expanded=False):
            st.markdown(", ".join(incubator))
            st.caption(
                "신규 상장 ETF는 RS 계산에 필요한 히스토리(70거래일)가 쌓일 때까지 스캔에서 제외됩니다. "
                "시간이 지나면 자동 편입되고, 등록 6개월 시점에 저품질이면 자동 정리 대상이 됩니다."
            )
    if not missing:
        return
    with st.expander(f"⚠️ 미수집 티커 {len(missing)}개 — 사유별 상세", expanded=False):
        by_key: dict = {}
        for m in missing:
            by_key.setdefault(m.get("reason_key", "?"), []).append(m)
        for key, items in by_key.items():
            reason = items[0].get("reason", key)
            tickers_str = ", ".join(i["ticker"] for i in items)
            st.markdown(f"- **{reason}** ({len(items)}개): {tickers_str}")
        if any(m.get("reason_key") == "no_data" for m in missing):
            st.info(
                "💡 '데이터 없음' 티커는 살아있는 종목이 아닐 가능성이 높아요. "
                "「🆕 ETF Universe 관리」의 정리(cleanup) 기능으로 유니버스에서 제거하면 "
                "다음 스캔부터 커버리지가 올라갑니다."
            )
        if any(m.get("reason_key") == "exhausted" for m in missing):
            st.warning("🔁 '재시도 소진' 티커는 일시 장애입니다 — 잠시 후 재스캔하면 대부분 수집됩니다.")


@st.cache_data(ttl=1800, show_spinner=False)
def _cached_etf_top30_holdings(etf_ticker: str):
    """ETF 구성종목 상위 30 [(심볼, 비중%)] — 라이브(FMP /etf/holdings) 우선, 비면 _ETF_CONSTITUENTS 폴백.
    반환: (holdings: [(sym, weight)], source: "live"|"fallback"|"none")
    cached_etf_tier3_analysis 와 동일한 소스 우선순위 — 교차체크 전용 경량 버전."""
    etf_u = str(etf_ticker or "").strip().upper()
    if not etf_u:
        return [], "none"
    live = _fmp_etf_holdings(etf_u, top_n=30)
    live = [(s, w) for s, w in live if "." not in s]
    if len(live) >= 3:
        return live, "live"
    fb = [str(s).strip().upper() for s in _ETF_CONSTITUENTS.get(etf_u, []) if "." not in str(s)]
    fb = list(dict.fromkeys(fb))[:30]
    if fb:
        return [(s, 0.0) for s in fb], "fallback"
    return [], "none"


def collect_recent_narrative_ticker_map(days: int = 7):
    """최근 N일 내러티브(현재 user)에서 종목 → 등급 집합 맵 구성.
    Winners = themes[].winners (주도주) · Emerging = themes[].expanding_to[].expected_tickers (2차 수혜).
    반환: (ticker_map: {ticker: set[str]}, record_count: int)"""
    ticker_map: dict = {}
    try:
        records = load_narrative_history_records() or []
    except Exception:
        return {}, 0
    cutoff = datetime.now(timezone.utc) - timedelta(days=max(1, int(days)))
    n_recent = 0
    for rec in records:
        if not isinstance(rec, dict):
            continue
        dt_utc = _narrative_parse_saved_at_utc(rec.get("saved_at"))
        if dt_utc is None or dt_utc < cutoff:
            continue
        analysis = rec.get("analysis") if isinstance(rec.get("analysis"), dict) else {}
        if not analysis:
            continue
        n_recent += 1
        try:
            for t in winners_tickers_from_theme_analysis(analysis):
                ticker_map.setdefault(str(t).strip().upper(), set()).add("Winners")
        except Exception:
            pass
        try:
            for t in emerging_tickers_from_theme_analysis(analysis):
                ticker_map.setdefault(str(t).strip().upper(), set()).add("Emerging")
        except Exception:
            pass
    return ticker_map, n_recent


def cross_check_early_signal_with_narratives(etf_tickers: list, days: int = 7, max_etfs: int = 10):
    """Early Signal ETF ↔ 최근 N일 내러티브 종목 교차체크 (구성종목 전개 방식).

    깔때기 역전 원칙의 기능화: '차트에서 찾고 → 뉴스로 확인한다'.
    - 매치 있음 → 가격+스토리 동시 포착 (확신도 상승)
    - 매치 없음 → 내러티브 미등장 = 아주 초기일 수 있음 (나쁜 신호 아님, 정밀검사 필수)

    반환: {"narr_records": int, "narr_tickers": int, "days": int,
           "results": {etf: {"matches": [(sym, "Winners/Emerging", weight%)], "source": str}}}
    """
    out = {"narr_records": 0, "narr_tickers": 0, "days": int(days), "results": {}}
    etfs = [str(t).strip().upper() for t in (etf_tickers or []) if str(t).strip()][:max_etfs]
    if not etfs:
        return out
    ticker_map, n_rec = collect_recent_narrative_ticker_map(days=days)
    out["narr_records"] = n_rec
    out["narr_tickers"] = len(ticker_map)
    if not ticker_map:
        return out
    for etf in etfs:
        try:
            holdings, source = _cached_etf_top30_holdings(etf)
        except Exception:
            holdings, source = [], "none"
        matches = []
        for sym, w in holdings:
            tiers = ticker_map.get(sym)
            if tiers:
                matches.append((sym, "/".join(sorted(tiers)), float(w or 0.0)))
        matches.sort(key=lambda x: x[2], reverse=True)
        out["results"][etf] = {"matches": matches, "source": source}
    return out


def save_early_signal_history(scan_df, xcheck: dict | None):
    """Early Signal 스캔 결과를 EarlySignal_History 시트에 append.
    '➡️ 유지'/'N/A' 는 제외(대부분을 차지하는 무신호 행으로 시트 비대화 방지) — 신호 행만 기록.
    저장 실패는 스캔 표시를 막지 않는다(비차단). 반환: (성공여부, 메시지)"""
    try:
        if scan_df is None or scan_df.empty:
            return False, "저장할 스캔 결과 없음"
        sig_df = scan_df[~scan_df["RS_Signal"].isin(["➡️ 유지", "N/A"])].copy()
        if sig_df.empty:
            return True, "신호 행 없음 — 저장 생략"
        ws, err = open_early_signal_history_worksheet()
        if err:
            return False, err
        match_results = (xcheck or {}).get("results", {}) if isinstance(xcheck, dict) else {}
        has_narr = bool((xcheck or {}).get("narr_tickers")) if isinstance(xcheck, dict) else False
        now_str = _narrative_now_et_string(datetime.now(timezone.utc))
        rows = []
        for _, r in sig_df.iterrows():
            tk = str(r.get("Ticker", "")).strip().upper()
            res = match_results.get(tk)
            if res is None:
                narr_match, detail = "", ""  # 교차체크 대상 아님(약화/급하락 등) 또는 내러티브 없음
            elif res.get("matches"):
                narr_match = "Y"
                detail = ", ".join(
                    f"{s}({tier})" + (f" {w:.1f}%" if w > 0 else "")
                    for s, tier, w in res["matches"][:5]
                )
            else:
                narr_match = "N" if has_narr else ""
                detail = ""
            rows.append([
                now_str, tk,
                r.get("RS_Now", ""), r.get("RS_1W_Ago", ""), r.get("RS_Change", ""),
                str(r.get("RS_Signal", "")), narr_match, detail,
            ])
        _safe_append_rows(ws, rows, value_input_option="USER_ENTERED")
        return True, f"{len(rows)}행 저장"
    except Exception as exc:
        return False, str(exc)


_ROTATION_BUCKET_MAP = {
    # 방어 계열
    "채권·현금성": ["BIL", "SGOV", "SHY", "IEF", "TLT", "TMF", "TBT", "AGG", "BND", "LQD", "HYG", "MUB", "GOVT", "VGSH", "VGIT"],
    "달러·귀금속": ["UUP", "GLD", "IAU", "SLV", "GDX", "GDXJ", "UGLD"],
    "인버스·변동성": ["SQQQ", "SH", "PSQ", "RWM", "SDOW", "SPXU", "UVXY", "VIXY", "FSTB"],
    "방어섹터(유틸·필수소비)": ["XLU", "VPU", "XLP", "KXI"],
    # 성장 계열
    "반도체·AI": ["SMH", "SOXX", "SOXQ", "XSD", "SOXL", "DRAM", "AIQ", "CHAT", "IGPT", "BOTZ", "ROBO", "NVDL", "USD"],
    "기술·성장": ["QQQ", "TQQQ", "XLK", "VGT", "FTEC", "IGV", "MTUM", "ARKK", "ARKW", "IWO", "IWM", "SPLG", "SPY", "VOO", "QQQM"],
    "소프트·클라우드·사이버": ["WCLD", "CLOU", "SKYY", "CIBR", "HACK", "BUG", "WISE"],
    # 그 외 자산군
    "에너지·원자재": ["USO", "XLE", "XOP", "OIH", "AMLP", "UNG", "DBC", "PDBC", "DBA", "CORN", "WEAT", "SOYB", "CANE", "MOO", "URA", "COPX", "XME", "FCG"],
    "금융·은행": ["XLF", "KBE", "KRE", "IAI", "KBWB", "IAT"],
    "헬스케어·바이오": ["XLV", "XBI", "IBB", "ARKG", "LABU", "IHI"],
    "해외·신흥국": ["EWH", "EWY", "EWC", "EWZ", "EWW", "EWJ", "EWG", "FXI", "KWEB", "MCHI", "CHIQ", "EEM", "VWO", "FM", "INDA", "EWT"],
    "크립토": ["BITO", "IBIT", "FBTC", "GBTC", "ETHE", "BITQ", "BTCU"],
    "소비·리테일": ["XRT", "XLY", "BETZ", "XHB", "ITB"],
}
_ROTATION_TICKER_TO_BUCKET = {tk: b for b, tks in _ROTATION_BUCKET_MAP.items() for tk in tks}
_ROTATION_DEFENSE = {"채권·현금성", "달러·귀금속", "인버스·변동성", "방어섹터(유틸·필수소비)"}
_ROTATION_GROWTH = {"반도체·AI", "기술·성장", "소프트·클라우드·사이버"}


def render_rotation_diagnosis(scan_df) -> None:
    """🧭 로테이션 진단 — Early Signal 결과의 부상/약화 리스트를 자산군 버킷으로 집계해
    큰 그림(리스크온/오프/섹터 로테이션)을 한 줄로 판정하고, 보유 종목과의 겹침을 경고.
    규칙 기반(LLM 미사용·결정적) · 추가 API 0콜 — 스캔 결과만으로 계산."""
    try:
        if scan_df is None or scan_df.empty or "RS_Signal" not in scan_df.columns:
            return
        rising_tks = scan_df[scan_df["RS_Signal"].isin(["🌱 Early Signal", "🚀 급부상"])]["Ticker"].tolist()
        weak_tks = scan_df[scan_df["RS_Signal"].isin(["⚠️ 모멘텀 약화", "🔴 급하락"])]["Ticker"].tolist()

        def _bucketize(tks):
            out = {}
            for t in tks:
                b = _ROTATION_TICKER_TO_BUCKET.get(str(t).strip().upper())
                if b:
                    out.setdefault(b, []).append(t)
            return out

        rise_b, weak_b = _bucketize(rising_tks), _bucketize(weak_tks)
        d_up = sum(len(v) for b, v in rise_b.items() if b in _ROTATION_DEFENSE)
        g_up = sum(len(v) for b, v in rise_b.items() if b in _ROTATION_GROWTH)
        d_down = sum(len(v) for b, v in weak_b.items() if b in _ROTATION_DEFENSE)
        g_down = sum(len(v) for b, v in weak_b.items() if b in _ROTATION_GROWTH)

        st.markdown("##### 🧭 로테이션 진단 — 세 리스트를 겹쳐 읽은 큰 그림")
        if d_up >= 3 and g_down >= 3:
            st.warning(
                f"⚠️ **리스크오프 로테이션 감지** — 방어자산(채권·현금성·달러·인버스) **{d_up}개 부상** · "
                f"기술/반도체/성장 **{g_down}개 약화**. 신규 성장주 진입은 보수적으로, 보유 성장 포지션은 청산 신호 주시."
            )
        elif g_up >= 3 and d_down >= 2 and d_up <= 1:
            st.success(
                f"🟢 **리스크온 로테이션 감지** — 성장 계열 **{g_up}개 부상** · 방어자산 **{d_down}개 약화**. "
                f"공격적 국면 — 단, 진입은 여전히 개별 종목 신호와 R:R 게이트 기준."
            )
        else:
            top_rise = max(rise_b.items(), key=lambda kv: len(kv[1]), default=(None, []))
            top_weak = max(weak_b.items(), key=lambda kv: len(kv[1]), default=(None, []))
            if top_rise[0] and top_weak[0] and top_rise[0] != top_weak[0]:
                st.info(
                    f"🔄 **섹터 로테이션 진행 중** — 자금 유입: **{top_rise[0]}** ({len(top_rise[1])}개) ← "
                    f"자금 이탈: **{top_weak[0]}** ({len(top_weak[1])}개)"
                )
            else:
                st.info("➡️ 뚜렷한 자산군 쏠림 없음 — 판단 유보 (개별 신호 기준으로 대응)")

        with st.expander("자산군별 상세 분포", expanded=False):
            if rise_b:
                st.markdown("**부상 (🌱+🚀):** " + " · ".join(
                    f"{b} {len(v)}개({', '.join(v[:6])}{'…' if len(v) > 6 else ''})"
                    for b, v in sorted(rise_b.items(), key=lambda kv: -len(kv[1]))
                ))
            if weak_b:
                st.markdown("**약화 (⚠️+🔴):** " + " · ".join(
                    f"{b} {len(v)}개({', '.join(v[:6])}{'…' if len(v) > 6 else ''})"
                    for b, v in sorted(weak_b.items(), key=lambda kv: -len(kv[1]))
                ))
            _unmapped = [t for t in rising_tks + weak_tks
                         if str(t).strip().upper() not in _ROTATION_TICKER_TO_BUCKET]
            if _unmapped:
                st.caption(f"버킷 미분류 {len(_unmapped)}개: {', '.join(_unmapped[:20])}"
                           + (" …" if len(_unmapped) > 20 else ""))

        # ── 보유 종목 겹침 경고 (핵심) ──
        try:
            _pf = load_portfolio()
            held = {str(t).strip().upper() for t in _pf.get("Ticker", pd.Series(dtype=str)).tolist()}
        except Exception:
            held = set()
        if held:
            overlap = [t for t in weak_tks if str(t).strip().upper() in held]
            if overlap:
                st.error(
                    f"🚨 **보유 종목이 약화 리스트에 {len(overlap)}개 겹칩니다: {', '.join(overlap)}** — "
                    f"아래 🛡️ 섹터 꺾임 스캔으로 확정 여부를 확인하고, 확정 시 [4단계] 매도 레이더에서 축소를 검토하세요. "
                    f"(개별주 보유분은 섹터 꺾임 감지가 해당 섹터 ETF로 커버)"
                )
    except Exception:
        pass  # 진단은 부가 정보 — 실패해도 스캔 표시를 막지 않음


def render_early_signal_xcheck(xcheck: dict | None) -> None:
    """Early Signal × 내러티브 교차체크 결과 렌더링 (라이브/복원 겸용).
    🔥 매치는 한 줄씩 강조, 미등장은 요약 한 줄 + expander 로 압축 (전수 교차체크 도배 방지)."""
    if not isinstance(xcheck, dict) or not xcheck:
        return
    st.markdown("##### 🔗 내러티브 교차체크 — 가격이 먼저, 스토리로 확인")

    # ── 복원 모드 (EarlySignal_History 시트에서 로드된 지난 스캔) ──
    if xcheck.get("restored"):
        for tk, detail in xcheck.get("match_lines", []):
            st.markdown(f"🔥 **{tk}** — 가격+스토리 동시 포착: {detail} → 우선 검토 대상")
        _nm = xcheck.get("nomatch_tickers", [])
        if _nm:
            st.markdown(f"🌱 내러티브 미등장 **{len(_nm)}개**: {', '.join(_nm)}")
        if not xcheck.get("match_lines") and not _nm:
            st.caption("지난 스캔에 교차체크 기록 없음 (당시 내러티브 부재 또는 교차체크 대상 아님)")
        return

    n_rec, n_tk, days = xcheck.get("narr_records", 0), xcheck.get("narr_tickers", 0), xcheck.get("days", 7)
    if n_rec == 0 or n_tk == 0:
        st.info(
            f"최근 {days}일 내러티브가 없어 교차체크를 건너뛰었어요. "
            "[1단계] 시장 내러티브를 먼저 생성하면 다음 스캔부터 자동 대조됩니다."
        )
        return
    st.caption(f"대조 기준: 최근 {days}일 내러티브 **{n_rec}건** · 등장 종목 **{n_tk}개** (Winners+Emerging)")
    results = xcheck.get("results", {})
    no_match, no_hold = [], []
    for etf, res in results.items():
        matches = res.get("matches") or []
        src_note = " *(대표종목 폴백 기준)*" if res.get("source") == "fallback" else ""
        if matches:
            detail = " · ".join(
                f"**{s}**({tier}" + (f" {w:.1f}%" if w > 0 else "") + ")"
                for s, tier, w in matches[:5]
            )
            st.markdown(f"🔥 **{etf}** — 가격+스토리 동시 포착: {detail}{src_note} → 우선 검토 대상")
        elif res.get("source") == "none":
            no_hold.append(etf)
        else:
            no_match.append(etf)
    if no_match:
        st.markdown(
            f"🌱 **내러티브 미등장 {len(no_match)}개** — 아무도 얘기 안 하는데 자금이 먼저 움직임 "
            f"(아주 초기일 수 있음 · 정밀검사 필수)"
        )
        with st.expander(f"미등장 목록 {len(no_match)}개", expanded=False):
            st.markdown(", ".join(no_match))
    if no_hold:
        st.caption(f"❔ 구성종목 정보 없음(교차체크 불가) {len(no_hold)}개: {', '.join(no_hold[:15])}"
                   + (" …" if len(no_hold) > 15 else ""))


@st.cache_data(ttl=600, show_spinner=False)
def load_last_early_signal_scan():
    """EarlySignal_History 시트에서 가장 최근 스캔 그룹 복원 (접속 시 영속 표시용).
    반환: (df|None, xcheck_restored|None, date_str)
    df 컬럼: Ticker, RS_Now, RS_1W_Ago, RS_Change, RS_Signal (신호 행만 — 저장 정책과 동일)."""
    try:
        ws, err = open_early_signal_history_worksheet()
        if err or ws is None:
            return None, None, ""
        vals = ws.get_all_values() or []
    except Exception:
        return None, None, ""
    if len(vals) < 2:
        return None, None, ""
    rows = [r for r in vals[1:] if len(r) >= 6 and str(r[0]).strip()]
    if not rows:
        return None, None, ""
    last_date = max(str(r[0]).strip() for r in rows)
    grp = [(r + [""] * 8)[:8] for r in rows if str(r[0]).strip() == last_date]
    recs, match_lines, nomatch = [], [], []
    for r in grp:
        tk = str(r[1]).strip().upper()
        if not tk:
            continue
        recs.append({
            "Ticker": tk,
            "RS_Now": to_float(r[2]), "RS_1W_Ago": to_float(r[3]), "RS_Change": to_float(r[4]),
            "RS_Signal": str(r[5]).strip(),
        })
        if str(r[6]).strip().upper() == "Y":
            match_lines.append((tk, str(r[7]).strip()))
        elif str(r[6]).strip().upper() == "N":
            nomatch.append(tk)
    if not recs:
        return None, None, ""
    df = pd.DataFrame(recs).sort_values("RS_Change", ascending=False, na_position="last")
    xcheck = {"restored": True, "date": last_date, "match_lines": match_lines, "nomatch_tickers": nomatch}
    return df, xcheck, last_date


def compute_rs_score_weekly_change(pool_tickers: list, spy_series_now: pd.Series = None):
    """
    1주 전 RS Score 대비 현재 RS Score 변화율 계산.
    - RS Score = 종목 3개월 수익률 - SPY 3개월 수익률
    - RS 변화 = (현재 RS) - (1주 전 RS) → 양수면 최근 1주간 시장 대비 강해짐

    v2 (전수 fetch + 투명 보고):
    - SPY 는 단독 robust fetch 로 최우선 확보 (단일 실패점 제거)
    - 유니버스는 _fmp_robust_batch_history_report 로 재시도 포함 전수 수집
    - 미수집 티커는 조용히 버리지 않고 사유와 함께 report 로 반환

    반환: (DataFrame [Ticker, RS_Now, RS_1W_Ago, RS_Change, RS_Signal],
           report {"total", "ok_count", "missing": [{"ticker","reason_key","reason"}], "spy_error"})
    """
    empty = pd.DataFrame()
    report = {"total": 0, "ok_count": 0, "missing": [], "spy_error": None}
    if not pool_tickers:
        return empty, report
    try:
        unique = list(dict.fromkeys(str(t).strip().upper() for t in pool_tickers if str(t).strip()))
        report["total"] = len(unique)

        # ── [1] SPY 기준 시리즈 최우선 확보 (실패 시 구체적 사유 반환) ──
        spy_df, spy_status = _fmp_price_history_robust("SPY", limit=130, return_status=True)
        spy = (
            pd.to_numeric(spy_df["Close"], errors="coerce").dropna()
            if (spy_df is not None and not spy_df.empty and "Close" in spy_df.columns)
            else pd.Series(dtype=float)
        )
        if len(spy) < 70:
            report["spy_error"] = (
                "SPY 기준 데이터 확보 실패"
                + (f" ({_RS_SCAN_MISS_REASONS.get(spy_status, spy_status)})" if spy_status != "ok"
                   else " (히스토리 70거래일 미만)")
            )
            return empty, report

        # ── [2] 유니버스 전수 fetch (재시도 포함 · 캐시 없음 · 상태 보고) ──
        fetch_targets = [t for t in unique if t != "SPY"]
        hist, status_map = _fmp_robust_batch_history_report(fetch_targets, limit=130)

        def _mark_missing(tk, key, bars=None):
            entry = {
                "ticker": tk, "reason_key": key,
                "reason": _RS_SCAN_MISS_REASONS.get(key, key),
            }
            if bars is not None:
                entry["bars"] = int(bars)
            report["missing"].append(entry)

        rows = []
        for tk in unique:
            if tk == "SPY":
                s = spy  # SPY 가 유니버스에 포함된 경우: 기준 시리즈 재사용 (RS ≈ 0)
            else:
                status = status_map.get(tk, "exhausted")
                if status != "ok":
                    _mark_missing(tk, status)
                    continue
                df_tk = hist.get(tk)
                if df_tk is None or df_tk.empty or "Close" not in df_tk.columns:
                    _mark_missing(tk, "no_data")
                    continue
                s = pd.to_numeric(df_tk["Close"], errors="coerce").dropna()
            if len(s) < 70:
                _mark_missing(tk, "short", bars=len(s))
                continue
            # 현재 RS (3개월 = 63거래일)
            rs_now = float((s.iloc[-1]/s.iloc[-64] - 1)*100 - (spy.iloc[-1]/spy.iloc[-64] - 1)*100) if len(s) >= 64 and len(spy) >= 64 else np.nan
            # 1주 전(5거래일 전) RS
            rs_1w = float((s.iloc[-6]/s.iloc[-69] - 1)*100 - (spy.iloc[-6]/spy.iloc[-69] - 1)*100) if len(s) >= 69 and len(spy) >= 69 else np.nan
            rs_change = float(rs_now - rs_1w) if pd.notna(rs_now) and pd.notna(rs_1w) else np.nan

            # 신호 분류
            if pd.notna(rs_change):
                if rs_now > 0 and rs_change > 2:
                    signal = "🚀 급부상"       # 강하면서 더 강해짐
                elif rs_now < 0 and rs_change > 2:
                    signal = "🌱 Early Signal"  # 약했는데 강해지기 시작 ← 핵심!
                elif rs_now > 0 and rs_change < -2:
                    signal = "⚠️ 모멘텀 약화"   # 강했는데 약해지기 시작 ← 매도 주의
                elif rs_change < -3:
                    signal = "🔴 급하락"
                else:
                    signal = "➡️ 유지"
            else:
                signal = "N/A"

            rows.append({
                "Ticker": tk,
                "RS_Now": round(rs_now, 2) if pd.notna(rs_now) else np.nan,
                "RS_1W_Ago": round(rs_1w, 2) if pd.notna(rs_1w) else np.nan,
                "RS_Change": round(rs_change, 2) if pd.notna(rs_change) else np.nan,
                "RS_Signal": signal,
            })
        df = pd.DataFrame(rows)
        if not df.empty:
            df = df.sort_values("RS_Change", ascending=False, na_position="last")
        report["ok_count"] = len(df)
        return df, report
    except Exception as exc:
        report["spy_error"] = report.get("spy_error") or f"예상치 못한 오류({type(exc).__name__}: {exc}) — 재스캔 권장"
        return pd.DataFrame(), report


def verify_emerging_with_quant(emerging_tickers: list, narrative_date: str = "") -> list[dict]:
    """
    내러티브 Emerging 종목을 정량 데이터로 교차 검증.
    "아직 안 오른 2차 수혜주"를 자동으로 분류.
    반환: [{"ticker", "rs_score", "mom_1m", "above_ma200", "vol_surge", "verdict", "verdict_emoji"}]
    """
    if not emerging_tickers:
        return []
    try:
        unique = list(dict.fromkeys(str(t).strip().upper() for t in emerging_tickers if str(t).strip()))
        all_tickers = list(dict.fromkeys(unique + ["SPY"]))
        # 느려도 확실하게: 재시도·버스트억제·빈결과 캐시안함. limit 220 → MA200 실제 계산.
        close_df = _fmp_robust_batch_close(all_tickers, limit=220)
        if close_df.empty:
            return []

        spy = pd.to_numeric(close_df.get("SPY", pd.Series(dtype=float)), errors="coerce").dropna()
        spy_3m = float((spy.iloc[-1]/spy.iloc[-64] - 1)*100) if len(spy) >= 64 else 0.0

        results = []
        for tk in unique:
            if tk not in close_df.columns:
                continue
            s = pd.to_numeric(close_df[tk], errors="coerce").dropna()
            if len(s) < 22:
                continue
            mom_1m = float((s.iloc[-1]/s.iloc[-22] - 1)*100) if len(s) >= 22 else np.nan
            mom_3m = float((s.iloc[-1]/s.iloc[-64] - 1)*100) if len(s) >= 64 else np.nan
            rs_score = float(mom_3m - spy_3m) if pd.notna(mom_3m) else np.nan
            ma200 = float(s.rolling(200, min_periods=150).mean().iloc[-1]) if len(s) >= 150 else np.nan
            above_ma200 = bool(s.iloc[-1] > ma200) if pd.notna(ma200) else None

            # 거래량 급증 (cached_timing_price_history 재사용)
            try:
                _hist_vol = cached_timing_price_history(tk)
                if not _hist_vol.empty and "Volume" in _hist_vol.columns:
                    vol = pd.to_numeric(_hist_vol["Volume"], errors="coerce").dropna()
                    vol_surge = float(vol.tail(5).mean() / vol.tail(21).mean()) if len(vol) >= 21 else np.nan
                else:
                    vol_surge = np.nan
            except Exception:
                vol_surge = np.nan

            # ── 핵심 판정 ─────────────────────────────────────────────────
            # 🎯 최적 매수 타이밍: RS 음수(아직 안 올랐음) + 거래량 급증(돈 들어오기 시작)
            # 🌱 얼리버드: RS 낮음 + 200일선 위 + 최근 모멘텀 상승
            # ✅ 이미 강세: RS 양수 + 모멘텀 확인 (늦지 않음)
            # ⏳ 대기: 아직 신호 없음
            # ❌ 하락 추세: RS 음수 + 200일선 아래

            if pd.notna(rs_score) and rs_score < 0 and pd.notna(vol_surge) and vol_surge >= 1.5:
                verdict = "🎯 최적 매수 타이밍"
                detail = f"RS {rs_score:+.1f}%p (아직 저평가) + 거래량 {vol_surge:.1f}x 급증"
            elif pd.notna(rs_score) and rs_score < 3 and above_ma200 and pd.notna(mom_1m) and mom_1m > 2:
                verdict = "🌱 얼리버드 기회"
                detail = f"RS {rs_score:+.1f}%p + 200일선 위 + 1개월 {mom_1m:+.1f}%"
            elif pd.notna(rs_score) and rs_score > 5 and above_ma200:
                verdict = "✅ 이미 강세 (진입 시 고점 주의)"
                detail = f"RS {rs_score:+.1f}%p + 200일선 위"
            elif above_ma200 is False:
                verdict = "❌ 하락 추세 (대기)"
                detail = "200일선 아래 — 아직 때가 아님"
            else:
                verdict = "⏳ 신호 대기"
                detail = f"RS {rs_score:+.1f}%p" if pd.notna(rs_score) else "데이터 부족"

            results.append({
                "ticker": tk,
                "rs_score": round(rs_score, 2) if pd.notna(rs_score) else None,
                "mom_1m": round(mom_1m, 2) if pd.notna(mom_1m) else None,
                "above_ma200": above_ma200,
                "vol_surge": round(vol_surge, 2) if pd.notna(vol_surge) else None,
                "verdict": verdict,
                "detail": detail,
                "current_price": round(float(s.iloc[-1]), 4) if not s.empty and pd.notna(s.iloc[-1]) else None,  # ✅ Watchlist saved_price용
            })

        results.sort(key=lambda x: (
            0 if "최적" in x["verdict"] else
            1 if "얼리" in x["verdict"] else
            2 if "이미" in x["verdict"] else
            3 if "대기" in x["verdict"] else 4
        ))
        return results
    except Exception:
        return []


def _classify_narrative_etfs(tickers_tuple: tuple) -> set:
    """후보 티커 중 ETF/펀드(isEtf/isFund) 집합 반환. _fmp_profile(캐시) 병렬 조회.
    개별주 단계(Phase 1)에 ETF가 섞여 들어온 경우 제거 대상 판별용."""
    tickers = [str(t).upper().strip() for t in dict.fromkeys(tickers_tuple) if str(t).strip()]
    if not tickers:
        return set()
    import concurrent.futures as _cf
    etf = set()

    def _one(tk):
        try:
            p = _fmp_profile(tk) or {}
            return tk, bool(p.get("isEtf") or p.get("isFund"))
        except Exception:
            return tk, False

    try:
        with _cf.ThreadPoolExecutor(max_workers=8) as ex:
            for fut in _cf.as_completed([ex.submit(_one, t) for t in tickers]):
                try:
                    tk, is_etf = fut.result()
                    if is_etf:
                        etf.add(tk)
                except Exception:
                    pass
    except Exception:
        return set()
    return etf


def _quant_verdict_emoji(verdict) -> str:
    """verdict 문자열 → 선두 판정 이모지 1개."""
    v = str(verdict or "")
    for e in ("🎯", "🌱", "✅", "❌"):
        if e in v:
            return e
    return "⏳"


def _fmt_quant_inline(tickers_csv, quant_map, tier: str = "", status_map=None) -> str:
    """티커 CSV → 종목별 정량 요약. 단계별 상세도 차등(화면 정리):
      - winner : 풀 정보 (판정 + RS + 200일선 + ⚠️불일치 플래그)
      - emerging: 판정 라벨만 (RS·200일선 숫자 생략)
      - expand : 판정 이모지 1개만 (티커 뒤 부착, 텍스트 없음)
    무지표 티커는 status_map으로 구분(new=🆕 / unchecked=🔁)."""
    status_map = status_map or {}
    parts = []
    for t in [x.strip().upper() for x in str(tickers_csv or "").split(",") if x.strip()]:
        if not t or t == "N/A":
            continue
        q = (quant_map or {}).get(t)
        if not q:
            stt = status_map.get(t)
            ic = "🆕" if stt == "new" else ("🔁" if stt == "unchecked" else "⏳")
            if tier == "expand":
                parts.append(f"{t}{ic}")
            elif tier == "emerging":
                parts.append(f"{t} {ic}")
            else:  # winner
                full = {"new": "🆕신규(데이터 축적 전)",
                        "unchecked": "🔁검증보류(재시도)"}.get(stt, "⏳정량부족")
                parts.append(f"{t} {full}")
            continue
        verdict = str(q.get("verdict", "") or "").strip()
        if tier == "expand":
            parts.append(f"{t}{_quant_verdict_emoji(verdict)}")
        elif tier == "emerging":
            parts.append(f"{t} {verdict}")
        else:  # winner: 풀 정보
            rs = q.get("rs_score")
            above = q.get("above_ma200")
            rs_s = f"RS{rs:+.1f}%p" if isinstance(rs, (int, float)) else ""
            ma_s = "200MA▲" if above else ("200MA▼" if above is False else "")
            flag = ""
            if above is False or (isinstance(rs, (int, float)) and rs < 0):
                flag = " ⚠️정량미확인"
            seg = " ".join(x for x in [verdict, rs_s, ma_s] if x)
            parts.append(f"{t} {seg}{flag}".strip())
    sep = "  " if tier == "expand" else " · "
    return sep.join(parts)


def detect_sector_momentum_reversal(universe_tickers: list):
    """
    섹터 꺾임 감지: 연속 2주 RS 하락 + 거래량 감소 + 가격 유지 패턴.

    v2 (전수 fetch + 투명 보고): Early Signal 과 동일한 robust 전수 수집으로 전환.
    - SPY 단독 robust fetch 최우선 확보 · 유니버스는 재시도 포함 전수 수집
    - 미수집 티커는 report 로 반환 (조용한 탈락 금지)

    반환: (alerts: [{"ticker","signal","rs_now","rs_1w","rs_change","vol_change","description"}],
           report {"total", "ok_count", "missing": [{"ticker","reason_key","reason"}], "spy_error"})
    """
    report = {"total": 0, "ok_count": 0, "missing": [], "spy_error": None}
    if not universe_tickers:
        return [], report
    try:
        unique = list(dict.fromkeys(t.strip().upper() for t in universe_tickers if t.strip()))
        report["total"] = len(unique)

        # ── SPY 기준 시리즈 최우선 확보 ──
        spy_df, spy_status = _fmp_price_history_robust("SPY", limit=130, return_status=True)
        spy = (
            pd.to_numeric(spy_df["Close"], errors="coerce").dropna()
            if (spy_df is not None and not spy_df.empty and "Close" in spy_df.columns)
            else pd.Series(dtype=float)
        )
        if len(spy) < 75:
            report["spy_error"] = (
                "SPY 기준 데이터 확보 실패"
                + (f" ({_RS_SCAN_MISS_REASONS.get(spy_status, spy_status)})" if spy_status != "ok"
                   else " (히스토리 75거래일 미만)")
            )
            return [], report

        # ── 유니버스 전수 fetch (재시도 포함 · 상태 보고) ──
        # 주의: 티커별 시리즈를 하나의 DataFrame 으로 결합하지 않는다 —
        # FMP 가 간헐적으로 중복 날짜 행을 반환하면 결합 시 duplicate-axis 예외로 전체가 죽는다.
        # compute_rs_score_weekly_change 와 동일하게 티커별 개별 처리(+중복 인덱스 방어).
        fetch_targets = [t for t in unique if t != "SPY"]
        hist, status_map = _fmp_robust_batch_history_report(fetch_targets, limit=130)
        spy = spy[~spy.index.duplicated(keep="last")]

        def _mark_missing(tk, key, reason=None, bars=None):
            entry = {
                "ticker": tk, "reason_key": key,
                "reason": reason or _RS_SCAN_MISS_REASONS.get(key, key),
            }
            if bars is not None:
                entry["bars"] = int(bars)
            report["missing"].append(entry)

        def calc_rs(s, spy, offset_start=0, offset_end=0):
            try:
                s_start = offset_start + 63
                s_end = offset_start
                spy_start = offset_start + 63
                spy_end = offset_start
                s_ret = float((s.iloc[-(1+s_end)] / s.iloc[-(1+s_start)] - 1) * 100)
                spy_ret = float((spy.iloc[-(1+spy_end)] / spy.iloc[-(1+spy_start)] - 1) * 100)
                return s_ret - spy_ret
            except Exception:
                return np.nan

        alerts = []
        ok_count = 0
        for tk in unique:
            if tk == "SPY":
                continue  # 기준 지수 자체는 꺾임 판정 대상 아님
            status = status_map.get(tk, "exhausted")
            if status != "ok":
                _mark_missing(tk, status)
                continue
            df_tk = hist.get(tk)
            if df_tk is None or df_tk.empty or "Close" not in df_tk.columns:
                _mark_missing(tk, "no_data")
                continue
            s = pd.to_numeric(df_tk["Close"], errors="coerce").dropna()
            s = s[~s.index.duplicated(keep="last")]
            if len(s) < 75:
                _mark_missing(tk, "short", "히스토리 75거래일 미만 — 신규 상장 (RS 계산 불가)", bars=len(s))
                continue
            ok_count += 1
            report.setdefault("ok_tickers", []).append(tk)

            rs_now = calc_rs(s, spy, 0)        # 현재 RS
            rs_1w = calc_rs(s, spy, 5)         # 1주 전 RS
            rs_2w = calc_rs(s, spy, 10)        # 2주 전 RS

            if not (pd.notna(rs_now) and pd.notna(rs_1w) and pd.notna(rs_2w)):
                continue

            rs_change_1w = rs_now - rs_1w
            rs_change_2w = rs_1w - rs_2w
            consecutive_drop = rs_change_1w < -1.5 and rs_change_2w < -1.5

            # 거래량 변화 (티커별 개별 시리즈 · 중복 인덱스 방어)
            vol_change = np.nan
            if "Volume" in df_tk.columns:
                vol = pd.to_numeric(df_tk["Volume"], errors="coerce").dropna()
                vol = vol[~vol.index.duplicated(keep="last")]
                if len(vol) >= 21:
                    recent_avg = float(vol.tail(5).mean())
                    baseline_avg = float(vol.tail(21).mean())
                    vol_change = (recent_avg / baseline_avg - 1) * 100 if baseline_avg > 0 else np.nan

            vol_declining = pd.notna(vol_change) and vol_change < -20

            # 신호 결정
            if consecutive_drop and rs_now > 0:
                signal = "⚠️ 매도 주의"
                desc = f"2주 연속 RS 하락 (현재 {rs_now:+.1f}%p → {rs_change_1w:+.1f}%p/주)"
                if vol_declining:
                    signal = "🔴 분산 매도 감지"
                    desc += f" + 거래량 {vol_change:+.0f}% 감소 (기관 매도 가능성)"
            elif rs_change_1w < -3 and rs_now < 0:
                signal = "🔴 급격한 약세 전환"
                desc = f"RS {rs_now:+.1f}%p + 주간 변화 {rs_change_1w:+.1f}%p"
            else:
                continue  # 정상 → 생략

            alerts.append({
                "ticker": tk,
                "signal": signal,
                "rs_now": round(rs_now, 2),
                "rs_1w": round(rs_1w, 2),
                "rs_change": round(rs_change_1w, 2),
                "vol_change": round(vol_change, 1) if pd.notna(vol_change) else None,
                "description": desc,
            })

        alerts.sort(key=lambda x: x["rs_change"])
        report["ok_count"] = ok_count
        return alerts, report
    except Exception as exc:
        report["spy_error"] = report.get("spy_error") or f"예상치 못한 오류({type(exc).__name__}: {exc}) — 재스캔 권장"
        return [], report


def build_pool_monthly_returns_table(pool_tickers):
    """Download pool prices once and calculate 1-month returns per ticker (공통 빌더 사용)."""
    df = build_etf_universe_returns_table(pool_tickers)
    if df.empty:
        return pd.DataFrame(columns=["Ticker", "1-Month (%)"])
    out = df[["Ticker", "1-Month (%)"]].copy()
    return out.sort_values("1-Month (%)", ascending=False, na_position="last").reset_index(drop=True)


