@st.cache_data(ttl=_DATA_CACHE_TTL, show_spinner=False)
def _fmp_etf_holdings(etf_ticker: str, top_n: int = 30) -> list:
    """FMP /etf/holdings — ETF 구성종목 상위 top_n [(심볼, 비중%)] (비중 내림차순)."""
    t = str(etf_ticker or "").strip().upper()
    k = _fmp_key()
    if not t or not k:
        return []
    try:
        r = requests.get(f"{_FMP_BASE}/etf/holdings?symbol={t}&apikey={k}", timeout=_FMP_TIMEOUT)
        if r.status_code != 200:
            return []
        data = r.json()
        if not isinstance(data, list):
            return []
        rows = []
        for it in data:
            if not isinstance(it, dict):
                continue
            sym = str(it.get("asset") or it.get("symbol") or "").strip().upper()
            if not sym:
                continue
            w = to_float(it.get("weightPercentage") or it.get("weight") or it.get("pctVal"))
            rows.append((sym, float(w) if pd.notna(w) else 0.0))
        rows.sort(key=lambda x: x[1], reverse=True)
        return rows[:top_n]
    except Exception:
        return []


@st.cache_data(ttl=_DATA_CACHE_TTL, show_spinner=False)
def _fmp_batch_pe(symbols_tuple: tuple) -> dict:
    """여러 심볼의 현재 PER → {symbol: pe(float|None)}.
    개별 종목 정밀검사와 동일하게 ratios-ttm 의 priceToEarningsRatioTTM 을 사용한다.
    (stable /quote 의 pe 는 비어 오고, /batch-quote 는 요금제에서 막힘. 적자 종목은 양수 PER이
    없으므로 None=N/A 로 둔다.)"""
    syms = [str(s).strip().upper() for s in symbols_tuple if str(s).strip()]
    out = {}
    for s in syms:
        pe = None
        try:
            rat = _fmp_ratios(s)
            v = to_float(rat.get("priceToEarningsRatioTTM")) if isinstance(rat, dict) else float("nan")
            if pd.notna(v) and v > 0:
                pe = float(v)
        except Exception:
            pe = None
        out[s] = pe
    return out


@st.cache_data(ttl=_DATA_CACHE_TTL, show_spinner=False)
def cached_etf_tier3_analysis(etf_ticker: str, sector_median_pe=None):
    """
    선택 ETF의 구성종목으로 2개 표 + ETF 요약을 만든다.
      - 주도주(Alpha Leaders): 1개월 수익률 상위 5
      - 저평가 후발주(Undervalued Laggards): 자유낙하 제외(1M>-20%) + 흑자(PER>0)
        + 저PER(섹터 중간 PER 또는 구성종목 중간값 미만) 중 수익률 하위(따라잡을 여지) → 싼 순 5
    구성종목 소스: 라이브(FMP /etf/holdings) 우선, 비면 _ETF_CONSTITUENTS 대표종목 폴백.
    반환: (leaders_df, laggards_df, source, etf_summary)
      source ∈ {"live","fallback","none"}
      etf_summary = {"ret_1m": float|None, "pe_median": float|None}  # ETF 1개월 수익률 / 구성종목 중간 PER
    """
    empty = pd.DataFrame(columns=["Ticker", "1-Month (%)", "PER"])
    etf_u = str(etf_ticker or "").strip().upper()

    # ETF 자체의 1개월 수익률 (구성종목과 무관하게 ETF 가격으로 계산)
    etf_ret = None
    try:
        _er = cached_pool_monthly_returns((etf_u,))
        if _er is not None and not _er.empty:
            _v = to_float(_er.iloc[0].get("1-Month (%)"))
            etf_ret = float(_v) if pd.notna(_v) else None
    except Exception:
        etf_ret = None
    summary = {"ret_1m": etf_ret, "pe_median": None}

    # 1) 라이브 우선 (FMP /etf/holdings)
    holdings = _fmp_etf_holdings(etf_u, top_n=30)
    live_syms = list(dict.fromkeys([s for s, _w in holdings if "." not in s]))
    if len(live_syms) >= 3:
        syms, source = live_syms[:30], "live"
    else:
        # 2) 대표종목 폴백 (요금제에 holdings 엔드포인트가 없을 때)
        fb = [str(s).strip().upper() for s in _ETF_CONSTITUENTS.get(etf_u, []) if "." not in str(s)]
        syms, source = list(dict.fromkeys(fb))[:30], "fallback"

    if len(syms) < 3:
        return empty, empty, "none", summary

    ret_df = cached_pool_monthly_returns(tuple(syms))  # [Ticker, 1-Month (%)] desc
    if ret_df is None or ret_df.empty:
        return empty, empty, "none", summary
    pe_map = _fmp_batch_pe(tuple(syms))

    df = ret_df.copy()
    df["Ticker"] = df["Ticker"].astype(str).str.strip().str.upper()
    df["_ret"] = pd.to_numeric(df["1-Month (%)"], errors="coerce")
    df["_pe"] = df["Ticker"].map(lambda s: pe_map.get(s))
    df["_pe"] = pd.to_numeric(df["_pe"], errors="coerce")
    df = df.dropna(subset=["_ret"]).copy()
    if df.empty:
        return empty, empty, "none", summary

    # 구성종목 중간 PER (양수만) → ETF 대표 PER
    _pe_pos = df.loc[df["_pe"] > 0, "_pe"]
    if not _pe_pos.empty:
        summary["pe_median"] = round(float(_pe_pos.median()), 1)

    # ── 주도주: 1개월 수익률 상위 5 ──
    leaders = df.sort_values("_ret", ascending=False).head(5).copy()

    # ── 저평가 후발주 (흑자·저PER·비자유낙하 중, 가장 덜 오른 후발주 순) ──
    cand = df[df["_ret"] > -20.0].copy()                       # 1) 자유낙하 제외
    cand = cand[cand["_pe"] > 0].copy()                        # 2) 흑자(PER>0)
    if not cand.empty:
        med = sector_median_pe if (sector_median_pe and sector_median_pe > 0) else cand["_pe"].median()
        if pd.notna(med):
            cheap = cand[cand["_pe"] < med]                    # 3) 저PER(중간값 미만)
            cand = cheap if not cheap.empty else cand          #    너무 타이트하면 흑자군 전체로 완화
    laggards = cand.sort_values("_ret", ascending=True).head(5).copy()  # 4) 덜 오른(후발) 순

    def _fmt(_d):
        if _d.empty:
            return empty
        o = pd.DataFrame({
            "Ticker": _d["Ticker"].values,
            "1-Month (%)": pd.to_numeric(_d["_ret"], errors="coerce").map(
                lambda x: f"{x:.2f}%" if pd.notna(x) else "N/A"),
            "PER": pd.to_numeric(_d["_pe"], errors="coerce").map(
                lambda x: f"{x:.1f}x" if pd.notna(x) else "N/A"),
        })
        return o.reset_index(drop=True)

    return _fmt(leaders), _fmt(laggards), source, summary


@st.cache_data(ttl=3600, show_spinner=False)
def _fmp_earnings_transcript(ticker: str) -> dict:
    """FMP /earning-call-transcript — 직전 분기 어닝콜 원문.
    반환: {"symbol": ..., "quarter": ..., "year": ..., "content": ...}
    """
    k = _fmp_key()
    if not k:
        return {}
    try:
        # 날짜 목록 먼저 조회 → 가장 최근 분기/연도 파악
        rd = requests.get(
            f"{_FMP_BASE}/earning-call-transcript-dates?symbol={ticker}&apikey={k}",
            timeout=_FMP_TIMEOUT,
        )
        if rd.status_code != 200:
            return {}
        dates = rd.json()
        if not isinstance(dates, list) or not dates:
            return {}
        # 첫 번째 항목이 가장 최근 (FMP 응답 내림차순)
        latest = dates[0]
        year = latest.get("year") or latest[0] if isinstance(latest, list) else latest.get("year")
        quarter = latest.get("quarter") or latest[1] if isinstance(latest, list) else latest.get("quarter")
        if not year or not quarter:
            return {}
        rt = requests.get(
            f"{_FMP_BASE}/earning-call-transcript?symbol={ticker}&year={year}&quarter={quarter}&apikey={k}",
            timeout=_FMP_TIMEOUT,
        )
        if rt.status_code == 200:
            d = rt.json()
            item = d[0] if isinstance(d, list) and d else (d if isinstance(d, dict) else {})
            return item
    except Exception:
        pass
    return {}


