# Trade_History 시트 — 매수/매도 기록 CRUD
# ──────────────────────────────────────────────────────────────────────────────

def open_trade_history_worksheet():
    """Quant_DB / Trade_History 탭. 없으면 자동 생성."""
    gc = get_gspread_client()
    if gc is None:
        return None, "Google 서비스 계정이 설정되지 않았습니다."
    try:
        ws = _ws_handle_required(_TRADE_HISTORY_WORKSHEET_TITLE)
        return ws, None
    except Exception as exc:
        msg = str(exc).lower()
        if "not found" in msg or "does not exist" in msg or "unable to find" in msg:
            try:
                sh = _open_quant_db()
                ws = sh.add_worksheet(title=_TRADE_HISTORY_WORKSHEET_TITLE, rows=5000, cols=8)
                ws.update([_TRADE_HISTORY_SHEET_COLS], range_name="A1:H1", value_input_option="USER_ENTERED")
                _invalidate_ws_handles()
                return ws, None
            except Exception as exc2:
                return None, f"Trade_History 시트를 만들 수 없습니다: {exc2}"
        return None, f"Trade_History 시트를 열 수 없습니다: {exc}"


@st.cache_data(ttl=300)
def _trade_history_all_values_cached():
    ws, err = open_trade_history_worksheet()
    if err or ws is None:
        return [], err
    try:
        return ws.get_all_values(), None
    except Exception as exc:
        return [], str(exc)


def _invalidate_trade_history_cache():
    _trade_history_all_values_cached.clear()


def load_trade_history(user_id: str) -> pd.DataFrame:
    """Trade_History 시트에서 해당 user_id 행만 로드."""
    empty = pd.DataFrame(columns=_TRADE_HISTORY_SHEET_COLS)
    if not user_id:
        return empty
    rows, err = _trade_history_all_values_cached()
    if err or not rows:
        return empty

    # 헤더가 없거나 비어있으면 자동으로 표준 헤더로 간주
    first_row_lower = [str(c).strip().lower() for c in rows[0]]
    has_valid_header = any(c in _TRADE_HISTORY_SHEET_COLS for c in first_row_lower)

    if not has_valid_header or len(rows) < 2:
        # 헤더 없이 데이터만 있는 경우 — 컬럼 수로 맞추기
        data_rows = rows if not has_valid_header else rows[1:]
        if not data_rows:
            return empty
        try:
            ncols = max(len(r) for r in data_rows)
            cols = _TRADE_HISTORY_SHEET_COLS[:ncols]
            df = pd.DataFrame([r[:ncols] for r in data_rows], columns=cols)
        except Exception:
            return empty
    else:
        try:
            df = pd.DataFrame(rows[1:], columns=first_row_lower)
        except Exception:
            return empty
        # 컬럼 정규화 (대소문자 불일치 보정)
        col_map = {c: s for c in df.columns for s in _TRADE_HISTORY_SHEET_COLS if c == s.lower()}
        df = df.rename(columns=col_map)

    for c in _TRADE_HISTORY_SHEET_COLS:
        if c not in df.columns:
            df[c] = ""

    df = df[df["user_id"].astype(str).str.strip() == str(user_id).strip()]
    df = df[_TRADE_HISTORY_SHEET_COLS].copy().reset_index(drop=True)
    df["shares"] = pd.to_numeric(df["shares"], errors="coerce")
    df["price"] = pd.to_numeric(df["price"], errors="coerce")
    return df


def append_trade_history_row(user_id: str, account: str, ticker: str, action: str,
                              shares: float, price: float, date: str, memo: str = "") -> tuple[bool, str]:
    """Trade_History 시트에 한 행 추가."""
    ws, err = open_trade_history_worksheet()
    if err or ws is None:
        return False, err or "시트를 열 수 없습니다."
    try:
        row = [
            str(user_id).strip(),
            str(account).strip(),
            str(ticker).strip().upper(),
            str(action).strip().upper(),
            str(round(float(shares), 6)),
            str(round(float(price), 6)),
            str(date).strip(),
            str(memo).strip(),
        ]
        _safe_append_rows(ws, row, value_input_option="USER_ENTERED")
        _invalidate_trade_history_cache()
        # ── 현금 자동 반영: 기록된 거래만 (BUY 차감 / SELL 증가) ──
        # 기록 없는 포지션 삭제는 여기를 타지 않으므로 현금이 움직이지 않는다(의도).
        try:
            _act = str(action).strip().upper()
            _amt = float(shares) * float(price)
            if _act == "BUY" and _amt > 0:
                adjust_account_cash(user_id, account, -_amt, note=f"{ticker} 매수")
            elif _act == "SELL" and _amt > 0:
                adjust_account_cash(user_id, account, +_amt, note=f"{ticker} 매도")
        except Exception:
            pass   # 현금 반영 실패가 거래 기록 자체를 무효화하지 않는다
        return True, ""
    except Exception as exc:
        return False, str(exc)


# ══════════════════════════════════════════════════════════════════════════════
# 💰 배당 재투자(DRIP) 엔진
#
# 설계 원칙
#  1) Portfolios(6열) 스키마 불변 — 설정/이력은 별도 시트 2개로 분리.
#  2) 멱등성: (ID, Account, Ticker, Ex_Date) 가 Dividend_Log 에 있으면 절대 재처리 안 함.
#  3) 현금 정합: 재투자 = `현금 +배당` → `BUY(-동액)` 2단계. net 0.
#     ⚠️ BUY 만 기록하면 append_trade_history_row 가 현금을 실제로 차감해버린다
#        (배당 입금이 없었으므로 잔고가 조용히 줄어듦). 순서를 바꾸면 안 된다.
#  4) 로그는 **확정 결정만 append**. 가격 미확보 건은 기록하지 않고 다음 접속에 재시도
#     (fail-open) — 행 업데이트가 필요 없어 시트 경합이 없다.
#  5) 결과는 어디까지나 **장부 근사치**. 실제 증권사 DRIP 체결가·ROC 처리와 다르다.
# ══════════════════════════════════════════════════════════════════════════════

def open_dividend_prefs_worksheet():
    """Quant_DB / Dividend_Prefs 탭. 없으면 자동 생성. (ws|None, err|None)"""
    gc = get_gspread_client()
    if gc is None:
        return None, "Google 서비스 계정(`gcp_service_account`)이 설정되지 않았습니다."
    try:
        last_col = chr(ord("A") + len(_DIVIDEND_PREFS_COLS) - 1)
        _ws_c = _ws_handle(_DIVIDEND_PREFS_SHEET_TITLE)
        if _ws_c is not None:
            return _ws_c, None
        sh = _open_quant_db()
        ws = sh.add_worksheet(title=_DIVIDEND_PREFS_SHEET_TITLE, rows=1000,
                              cols=len(_DIVIDEND_PREFS_COLS))
        ws.update([_DIVIDEND_PREFS_COLS], range_name=f"A1:{last_col}1",
                  value_input_option="USER_ENTERED")
        _invalidate_ws_handles()
        return ws, None
    except Exception as exc:
        return None, f"Dividend_Prefs 워크시트 열기/생성 실패: {exc}"


@st.cache_data(ttl=300, show_spinner=False)
def _dividend_prefs_all_values_cached():
    ws, err = open_dividend_prefs_worksheet()
    if err or ws is None:
        return [], err
    try:
        return ws.get_all_values() or [], None
    except Exception as exc:
        return [], str(exc)


def _invalidate_dividend_prefs_cache():
    try:
        _dividend_prefs_all_values_cached.clear()
    except Exception:
        pass


def load_dividend_prefs(user_id: str) -> dict:
    """해당 user_id 의 종목별 배당 처리 모드. 반환: {(account_lower, TICKER): mode}."""
    uid = str(user_id or "").strip()
    if not uid:
        return {}
    try:
        vals, err = _dividend_prefs_all_values_cached()
    except Exception:
        return {}
    if err or not vals or len(vals) < 2:
        return {}
    ncol = len(_DIVIDEND_PREFS_COLS)
    out = {}
    for r in vals[1:]:
        r = (list(r) + [""] * ncol)[:ncol]
        if str(r[0]).strip().upper() != uid.upper():
            continue
        acct = str(r[1]).strip()
        tk = str(r[2]).strip().upper()
        mode = str(r[3]).strip().lower()
        if not acct or not tk or mode not in _DIVIDEND_MODES:
            continue
        out[(acct.lower(), tk)] = mode
    return out


def get_dividend_mode(prefs: dict, account: str, ticker: str) -> str:
    """저장된 모드 조회. 미설정이면 기본값('ask')."""
    key = (str(account or "").strip().lower(), str(ticker or "").strip().upper())
    return str((prefs or {}).get(key, _DIVIDEND_MODE_DEFAULT))


def save_dividend_pref(user_id: str, account: str, ticker: str, mode: str) -> tuple[bool, str]:
    """(ID, Account, Ticker) 한 행만 교체/추가. 다른 행은 보존."""
    uid = str(user_id or "").strip()
    acct = str(account or "").strip()
    tk = str(ticker or "").strip().upper()
    md = str(mode or "").strip().lower()
    if not uid or not acct or not tk:
        return False, "user_id / 계좌 / 티커가 비어 있습니다."
    if md not in _DIVIDEND_MODES:
        return False, f"알 수 없는 모드: {mode}"
    ws, err = open_dividend_prefs_worksheet()
    if err or ws is None:
        return False, err or "시트를 열 수 없습니다."
    ncol = len(_DIVIDEND_PREFS_COLS)
    last_col = chr(ord("A") + ncol - 1)
    try:
        vals = ws.get_all_values() or []
        keep = []
        for r in vals[1:]:
            r = (list(r) + [""] * ncol)[:ncol]
            if not str(r[0]).strip():
                continue
            if (str(r[0]).strip().upper() == uid.upper()
                    and str(r[1]).strip().lower() == acct.lower()
                    and str(r[2]).strip().upper() == tk):
                continue
            keep.append(r)
        rows = ([_DIVIDEND_PREFS_COLS] + keep
                + [[uid, acct, tk, md, _narrative_now_et_string()]])
        ws.clear()
        ws.update(rows, range_name=f"A1:{last_col}{len(rows)}",
                  value_input_option="USER_ENTERED")
        _invalidate_dividend_prefs_cache()
        return True, ""
    except Exception as exc:
        return False, str(exc)


