                    em_freq["평균점수"] = em_freq["평균점수"].round(1)

                    st.markdown("**🌱 자주 등장한 Emerging 종목 (신뢰도 높은 신호)**")
                    st.dataframe(em_freq.head(15), use_container_width=True, hide_index=True)

